/* ======== v2/10_comp.js ======== */
/* ================= utilidades de formato ================= */
const COR={ink:'#00205B',ouro:'#C9A84C',alerta:'#8C2332',ok:'#2E6B4F',aten:'#9A6B10',
  mudo:'#5B6475',regua:'#E2DFD6',azul2:'#3D5A8A',roxo:'#6B4E8C',sup:'#FFFFFF',
  c1:'#1F6F5C',c2:'#8C4A1F',c3:'#4A3B8C'};
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const pct=(v,d=1)=>v===null||v===undefined?'n/d':(100*v).toFixed(d).replace('.',',')+'%';
const n2=(v,d=2)=>v===null||v===undefined?'n/d':Number(v).toFixed(d).replace('.',',');
const rs=v=>v===null||v===undefined?'n/d':'R$ '+Math.round(v).toLocaleString('pt-BR');
const rsk=v=>v===null||v===undefined?'n/d':Math.abs(v)>=1e6?'R$ '+(v/1e6).toFixed(2).replace('.',',')+' mi'
  :Math.abs(v)>=1e4?'R$ '+Math.round(v/1e3)+' mil':rs(v);
const SELOS={sint:['s-sint','Exemplo sintético'],obs:['s-obs','Dado observado'],
  doc:['s-doc','Documento institucional'],esq:['s-esq','Esquema sem escala'],
  rec:['s-rec','Recalculado aqui']};
function selo(t){const [c,n]=SELOS[t]||SELOS.sint;return `<span class="selo ${c}">${n}</span>`;}
function tab(cols,linhas,titulo){
  return `<details class="so-estudo"><summary>${esc(titulo||'Ver os números')}</summary>
   <div class="rolax"><table><thead><tr>${cols.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead>
   <tbody>${linhas.map(l=>`<tr>`+l.map((v,i)=>i?`<td>${esc(v)}</td>`:`<th scope="row">${esc(v)}</th>`).join('')
   +`</tr>`).join('')}</tbody></table></div></details>`;
}
const svg=(w,h,corpo,rot)=>`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(rot||'')}"
  style="font-family:system-ui,sans-serif">${corpo}</svg>`;

/* ================= eixos ================= */
function eixos({w,h,L,R,T,B,yMin,yMax,yTicks,yFmt,rotY,rotX,xTicks,bandas}){
  const py=v=>T+(h-T-B)*(1-(v-yMin)/(yMax-yMin));
  let s='';
  if(bandas)for(const b of bandas)s+=`<rect x="${L}" y="${py(b.ate).toFixed(1)}" width="${w-L-R}"
    height="${Math.max(py(b.de)-py(b.ate),0).toFixed(1)}" fill="${b.cor}" opacity=".45"/>`;
  for(const t of yTicks)s+=`<line x1="${L}" y1="${py(t).toFixed(1)}" x2="${w-R}" y2="${py(t).toFixed(1)}"
    stroke="${COR.regua}"/><text x="${L-6}" y="${(py(t)+4).toFixed(1)}" text-anchor="end" font-size="12"
    fill="${COR.mudo}">${esc(yFmt(t))}</text>`;
  s+=`<line x1="${L}" y1="${T}" x2="${L}" y2="${h-B}" stroke="${COR.mudo}" stroke-width="1.3"/>
   <line x1="${L}" y1="${h-B}" x2="${w-R}" y2="${h-B}" stroke="${COR.mudo}" stroke-width="1.3"/>
   <text transform="translate(12,${T+(h-T-B)/2}) rotate(-90)" text-anchor="middle" font-size="12.5"
    fill="${COR.ink}" font-weight="600">${esc(rotY)}</text>
   <text x="${L+(w-L-R)/2}" y="${h-5}" text-anchor="middle" font-size="12.5" fill="${COR.ink}"
    font-weight="600">${esc(rotX)}</text>`;
  if(xTicks)for(const t of xTicks){
    const anc=t.x<=L+2?'start':t.x>=w-R-2?'end':'middle';
    s+=`<text x="${t.x.toFixed(1)}" y="${h-B+16}" text-anchor="${anc}"
    font-size="11.5" fill="${COR.mudo}">${esc(t.r)}</text>`;}
  return {s,py};
}
function legenda(series,L,T,w){
  let x=L+4,y=T-12,linha=0,s='';
  for(const se of series.filter(k=>k.nome)){
    const larg=28+se.nome.length*6.9;
    if(x+larg>w-10){x=L+4;linha++;y=T-12+linha*14;}
    s+=`<line x1="${x}" y1="${y-3}" x2="${x+16}" y2="${y-3}" stroke="${se.cor}" stroke-width="2.5"
      ${se.tracejada?'stroke-dasharray="6 3"':''}/>
      <text x="${x+21}" y="${y}" font-size="11.5" fill="#333">${esc(se.nome)}</text>`;
    x+=larg;}
  return {s,linhas:linha+1};
}
/* linhas com legenda que quebra e margem esquerda dinâmica */
function chLinhas({series,xMin,xMax,yMin,yMax,yTicks,xTicks,yTit,xTit,yFmt=v=>pct(v,0),
  w=640,h=340,bandas,marcas,anotacoes,diag,segmentos}){
  const larg=Math.max(...yTicks.map(t=>String(yFmt(t)).length));
  const leg=legenda(series,Math.max(62,26+larg*6.8),34,w);
  const L=Math.max(62,26+larg*6.8),R=18,T=30+(leg.linhas-1)*14,B=46;
  const px=v=>L+(w-L-R)*(v-xMin)/(xMax-xMin);
  const {s:base,py}=eixos({w,h,L,R,T,B,yMin,yMax,yTicks,yFmt,rotY:yTit,rotX:xTit,
    xTicks:xTicks.map(t=>({x:px(t.v),r:t.r})),bandas});
  let s=base+legenda(series,L,T,w).s;
  if(diag)s+=`<line x1="${px(xMin)}" y1="${py(yMin)}" x2="${px(xMax)}" y2="${py(yMax)}"
    stroke="${COR.mudo}" stroke-width="1.2" stroke-dasharray="6 4"/>`;
  for(const se of series){
    const d=se.pts.map((p,i)=>(i?'L':'M')+px(p[0]).toFixed(1)+' '+py(p[1]).toFixed(1)).join('');
    if(se.area)s+=`<path d="${d}L${px(se.pts[se.pts.length-1][0]).toFixed(1)} ${py(yMin).toFixed(1)}
      L${px(se.pts[0][0]).toFixed(1)} ${py(yMin).toFixed(1)}Z" fill="${se.cor}" opacity=".09"/>`;
    s+=`<path d="${d}" fill="none" stroke="${se.cor}" stroke-width="${se.larg||2.5}"
      ${se.tracejada?'stroke-dasharray="7 4"':''} stroke-linejoin="round"/>`;}
  if(segmentos)for(const g of segmentos)
    s+=`<line x1="${px(g.x).toFixed(1)}" y1="${py(g.y1).toFixed(1)}" x2="${px(g.x).toFixed(1)}"
      y2="${py(g.y2).toFixed(1)}" stroke="${g.cor||COR.alerta}" stroke-width="${g.larg||3}"/>
      <circle cx="${px(g.x).toFixed(1)}" cy="${py(g.y1).toFixed(1)}" r="3.4" fill="${g.cor||COR.alerta}"/>
      <circle cx="${px(g.x).toFixed(1)}" cy="${py(g.y2).toFixed(1)}" r="3.4" fill="${g.cor||COR.alerta}"/>
      ${g.r?`<text x="${(px(g.x)+(g.anc==='end'?-8:8)).toFixed(1)}"
      y="${(g.ly!==undefined?py(g.ly):(py(g.y1)+py(g.y2))/2+4).toFixed(1)}"
      text-anchor="${g.anc||'start'}" font-size="12.5" font-weight="700"
      fill="${g.cor||COR.alerta}">${esc(g.r)}</text>`:''}`;
  if(marcas)for(const m of marcas){
    s+=`<circle cx="${px(m.x).toFixed(1)}" cy="${py(m.y).toFixed(1)}" r="${m.r0||5}"
      fill="${m.cor||COR.alerta}" stroke="#fff" stroke-width="1.6"/>`;
    if(m.r)s+=`<text x="${(px(m.x)+9).toFixed(1)}" y="${(py(m.y)-8).toFixed(1)}" font-size="11.5"
      font-weight="700" fill="${m.cor||COR.alerta}" text-anchor="${m.anc||'start'}">${esc(m.r)}</text>`;}
  if(anotacoes)for(const a of anotacoes)
    s+=`<text x="${px(a.x).toFixed(1)}" y="${py(a.y).toFixed(1)}" font-size="11.5"
      fill="${a.cor||COR.mudo}" text-anchor="${a.anc||'start'}" font-weight="600">${esc(a.t)}</text>`;
  return svg(w,h,s,yTit+' por '+xTit);
}
function chBarras({dados,yMax,yTit,xTit,w=620,h=320,fmt=v=>pct(v,1),destaque,rotXinc}){
  const yTicks=[0,.25,.5,.75,1].map(f=>yMax*f);
  const larg=Math.max(...yTicks.map(t=>String(fmt(t)).length));
  const L=Math.max(58,26+larg*6.8),R=16,T=22,B=rotXinc?58:44;
  const n=dados.length,gap=(w-L-R)/n,bw=gap*0.64;
  const {s:base,py}=eixos({w,h,L,R,T,B,yMin:0,yMax,yTicks,yFmt:fmt,rotY:yTit,rotX:xTit,
    xTicks:rotXinc?null:dados.map((d,i)=>({x:L+gap*i+gap/2,r:d.r}))});
  let s=base;
  dados.forEach((d,i)=>{
    const x=L+gap*i+(gap-bw)/2,y=py(d.v),alt=Math.max(h-B-y,0);
    const cor=d.cor||(destaque===i?COR.alerta:COR.ink);
    s+=`<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${bw.toFixed(1)}"
      height="${alt.toFixed(1)}" fill="${cor}" rx="1"/>`;
    if(d.lo!==undefined&&d.lo!==null){const cx=x+bw/2;
      s+=`<line x1="${cx.toFixed(1)}" y1="${py(d.lo).toFixed(1)}" x2="${cx.toFixed(1)}"
        y2="${py(d.hi).toFixed(1)}" stroke="${COR.mudo}" stroke-width="1.5"/>
        <line x1="${(cx-4).toFixed(1)}" y1="${py(d.hi).toFixed(1)}" x2="${(cx+4).toFixed(1)}"
        y2="${py(d.hi).toFixed(1)}" stroke="${COR.mudo}" stroke-width="1.5"/>
        <line x1="${(cx-4).toFixed(1)}" y1="${py(d.lo).toFixed(1)}" x2="${(cx+4).toFixed(1)}"
        y2="${py(d.lo).toFixed(1)}" stroke="${COR.mudo}" stroke-width="1.5"/>`;}
    s+=`<text x="${(x+bw/2).toFixed(1)}" y="${(py(d.hi!==undefined&&d.hi!==null?d.hi:d.v)-5).toFixed(1)}"
      text-anchor="middle" font-size="11.5" font-weight="700" fill="${cor}">${esc(fmt(d.v))}</text>`;
    if(rotXinc)s+=`<text x="${(x+bw/2).toFixed(1)}" y="${h-B+14}" text-anchor="end" font-size="11"
      fill="${COR.mudo}" transform="rotate(-38 ${(x+bw/2).toFixed(1)} ${h-B+14})">${esc(d.r)}</text>`;
  });
  return svg(w,h,s,yTit);
}
function chBarrasH({dados,xMax,xTit,w=600,h=280,limites}){
  const L=Math.max(...dados.map(d=>d.r.length))*6.3+16,R=50,T=20,B=40;
  const gap=(h-T-B)/dados.length,bh=gap*0.6,px=v=>L+(w-L-R)*v/xMax;
  let s='';
  for(let t=0;t<=4;t++){const v=xMax*t/4;
    s+=`<line x1="${px(v).toFixed(1)}" y1="${T}" x2="${px(v).toFixed(1)}" y2="${h-B}" stroke="${COR.regua}"/>
     <text x="${px(v).toFixed(1)}" y="${h-B+15}" text-anchor="middle" font-size="11" fill="${COR.mudo}">${n2(v,2)}</text>`;}
  if(limites)for(const l of limites)
    s+=`<line x1="${px(l.v).toFixed(1)}" y1="${T-3}" x2="${px(l.v).toFixed(1)}" y2="${h-B}"
      stroke="${l.cor}" stroke-width="1.4" stroke-dasharray="5 3"/>
      <text x="${px(l.v).toFixed(1)}" y="${T-6}" text-anchor="middle" font-size="10.5"
      fill="${l.cor}" font-weight="700">${esc(l.r)}</text>`;
  dados.forEach((d,i)=>{const y=T+gap*i+(gap-bh)/2;
    s+=`<rect x="${L}" y="${y.toFixed(1)}" width="${Math.max(px(d.v)-L,1).toFixed(1)}"
      height="${bh.toFixed(1)}" fill="${d.cor||COR.ink}" rx="1"/>
      <text x="${L-7}" y="${(y+bh/2+4).toFixed(1)}" text-anchor="end" font-size="11.5" fill="#333">${esc(d.r)}</text>
      <text x="${(px(d.v)+5).toFixed(1)}" y="${(y+bh/2+4).toFixed(1)}" font-size="11" font-weight="700"
      fill="${d.cor||COR.ink}">${esc(d.fmt||n2(d.v,2))}</text>`;});
  s+=`<text x="${L+(w-L-R)/2}" y="${h-5}" text-anchor="middle" font-size="12" fill="${COR.ink}"
    font-weight="600">${esc(xTit)}</text>`;
  return svg(w,h,s,xTit);
}
/* calibração: previsto contra observado, com Wilson */
function chCalib({bins,w=470,h=380,mx}){
  const L=58,R=18,T=22,B=46;
  mx=mx||Math.max(...bins.map(b=>Math.max(b.prev,b.hi)))*1.1;
  const px=v=>L+(w-L-R)*v/mx,py=v=>T+(h-T-B)*(1-v/mx);
  let s='';
  for(const t of [0,mx/4,mx/2,3*mx/4,mx]){
    s+=`<line x1="${L}" y1="${py(t).toFixed(1)}" x2="${w-R}" y2="${py(t).toFixed(1)}" stroke="${COR.regua}"/>
     <text x="${L-6}" y="${(py(t)+4).toFixed(1)}" text-anchor="end" font-size="11" fill="${COR.mudo}">${pct(t,0)}</text>
     <text x="${px(t).toFixed(1)}" y="${h-B+15}" text-anchor="middle" font-size="11" fill="${COR.mudo}">${pct(t,0)}</text>`;}
  s+=`<line x1="${px(0)}" y1="${py(0)}" x2="${px(mx)}" y2="${py(mx)}" stroke="${COR.mudo}"
    stroke-width="1.3" stroke-dasharray="6 4"/>`;
  for(const b of bins)s+=`<line x1="${px(b.prev).toFixed(1)}" y1="${py(b.lo).toFixed(1)}"
    x2="${px(b.prev).toFixed(1)}" y2="${py(b.hi).toFixed(1)}" stroke="${COR.azul2}" stroke-width="1.4" opacity=".75"/>`;
  s+=`<path d="${bins.map((b,i)=>(i?'L':'M')+px(b.prev).toFixed(1)+' '+py(b.obs).toFixed(1)).join('')}"
    fill="none" stroke="${COR.ink}" stroke-width="2.2"/>`;
  for(const b of bins)s+=`<circle cx="${px(b.prev).toFixed(1)}" cy="${py(b.obs).toFixed(1)}"
    r="${(3+Math.sqrt(b.n)/8).toFixed(1)}" fill="${COR.ink}" stroke="#fff" stroke-width="1.2"/>`;
  s+=`<line x1="${L}" y1="${T}" x2="${L}" y2="${h-B}" stroke="${COR.mudo}" stroke-width="1.3"/>
   <line x1="${L}" y1="${h-B}" x2="${w-R}" y2="${h-B}" stroke="${COR.mudo}" stroke-width="1.3"/>
   <text transform="translate(12,${T+(h-T-B)/2}) rotate(-90)" text-anchor="middle" font-size="12"
    fill="${COR.ink}" font-weight="600">Frequência observada</text>
   <text x="${L+(w-L-R)/2}" y="${h-5}" text-anchor="middle" font-size="12" fill="${COR.ink}"
    font-weight="600">PD média prevista na faixa</text>`;
  return svg(w,h,s,'calibração');
}
/* duas distribuições lado a lado */
function chDuplaDist({ref,cur,rotulos,nomeRef,nomeCur,yTit,xTit,w=620,h=300,destaque}){
  const L=52,R=14,T=30,B=44,n=ref.length,gap=(w-L-R)/n,bw=gap*0.36;
  const yMax=Math.max(...ref,...cur)*1.22;
  const {s:base,py}=eixos({w,h,L,R,T,B,yMin:0,yMax,yTicks:[0,yMax/3,2*yMax/3,yMax],
    yFmt:v=>pct(v,0),rotY:yTit,rotX:xTit,xTicks:rotulos.map((r,i)=>({x:L+gap*i+gap/2,r}))});
  let s=base;
  for(let i=0;i<n;i++){const x=L+gap*i+gap/2;
    const op=destaque!==undefined&&destaque!==i?'.28':'1';
    s+=`<rect x="${(x-bw-1).toFixed(1)}" y="${py(ref[i]).toFixed(1)}" width="${bw.toFixed(1)}"
      height="${Math.max(h-B-py(ref[i]),0).toFixed(1)}" fill="${COR.ink}" opacity="${op}"/>
      <rect x="${(x+1).toFixed(1)}" y="${py(cur[i]).toFixed(1)}" width="${bw.toFixed(1)}"
      height="${Math.max(h-B-py(cur[i]),0).toFixed(1)}" fill="${COR.ouro}" opacity="${op}"/>`;}
  s+=`<rect x="${L+4}" y="${T-18}" width="11" height="8" fill="${COR.ink}"/>
    <text x="${L+19}" y="${T-11}" font-size="11" fill="#333">${esc(nomeRef)}</text>
    <rect x="${L+28+nomeRef.length*6}" y="${T-18}" width="11" height="8" fill="${COR.ouro}"/>
    <text x="${L+43+nomeRef.length*6}" y="${T-11}" font-size="11" fill="#333">${esc(nomeCur)}</text>`;
  return svg(w,h,s,yTit);
}

