/* barra de composição de um valor */
function barraFatia(partes,{larg=560,alt=64,total}={}){
  total=total||partes.reduce((s,p)=>s+Math.abs(p.v),0);
  let x=10,s='';
  for(const p of partes){const w=Math.max((Math.abs(p.v)/total)*(larg-20),1);
    s+=`<rect x="${x.toFixed(1)}" y="14" width="${w.toFixed(1)}" height="26" fill="${p.cor}"/>
     ${w>52?`<text x="${(x+w/2).toFixed(1)}" y="31" text-anchor="middle" font-size="11" font-weight="700"
     fill="#fff">${esc(p.fmt||rsk(p.v))}</text>`:''}
     <text x="${(x+w/2).toFixed(1)}" y="54" text-anchor="middle" font-size="10.5"
     fill="${COR.mudo}">${w>52?esc(p.r):''}</text>`;
    x+=w;}
  return svg(larg,alt,s,'composição');
}
