/* ======== js/qr.js ======== */
/* Codificador QR Model 2, modo byte, nivel de correcao M.
   Implementacao propria: a pagina nao carrega nenhuma biblioteca externa.
   Versoes 1 a 15. Retorna matriz booleana (true = modulo escuro).          */
const QR_CAP = [14,26,42,62,84,106,122,152,180,213,251,287,331,362,412];
const QR_EC = [ // [ec por bloco, g1, d1, g2, d2]
 [10,1,16,0,0],[16,1,28,0,0],[26,1,44,0,0],[18,2,32,0,0],[24,2,43,0,0],
 [16,4,27,0,0],[18,4,31,0,0],[22,2,38,2,39],[22,3,36,2,37],[26,4,43,1,44],
 [30,1,50,4,51],[22,6,36,2,37],[22,8,37,1,38],[24,4,40,5,41],[24,5,41,5,42]];
const QR_ALIGN = [[],[6,18],[6,22],[6,26],[6,30],[6,34],[6,22,38],[6,24,42],[6,26,46],
 [6,28,50],[6,30,54],[6,32,58],[6,34,62],[6,26,46,66],[6,26,48,70]];

const GF_EXP = new Uint8Array(512), GF_LOG = new Uint8Array(256);
(function () { let x = 1;
  for (let i = 0; i < 255; i++) { GF_EXP[i] = x; GF_LOG[x] = i; x <<= 1; if (x & 0x100) x ^= 0x11d; }
  for (let i = 255; i < 512; i++) GF_EXP[i] = GF_EXP[i - 255]; })();
const gmul = (a, b) => (a === 0 || b === 0) ? 0 : GF_EXP[GF_LOG[a] + GF_LOG[b]];

function rsGen(n) { let p = [1];
  for (let i = 0; i < n; i++) { const q = [...p, 0];
    for (let j = 0; j < p.length; j++) q[j + 1] ^= gmul(p[j], GF_EXP[i]);
    p = q; } return p; }
function rsEnc(data, n) {
  const g = rsGen(n), r = new Array(n).fill(0);
  for (const d of data) { const f = d ^ r[0]; r.shift(); r.push(0);
    if (f !== 0) for (let i = 0; i < n; i++) r[i] ^= gmul(g[i + 1], f); }
  return r;
}
const bch15 = d => { let v = d << 10;
  for (let i = 4; i >= 0; i--) if (v & (1 << (i + 10))) v ^= 0x537 << i;
  return ((d << 10) | v) ^ 0x5412; };
const bch18 = d => { let v = d << 12;
  for (let i = 5; i >= 0; i--) if (v & (1 << (i + 12))) v ^= 0x1f25 << i;
  return (d << 12) | v; };

function qrMatrix(texto) {
  const bytes = Array.from(new TextEncoder().encode(texto));
  let v = 0; while (v < 15 && bytes.length > QR_CAP[v]) v++;
  if (bytes.length > QR_CAP[14]) throw new Error('URL longa demais para QR versao 15');
  const ver = v + 1, size = 17 + 4 * ver;
  const [ecn, g1, d1, g2, d2] = QR_EC[v];
  const totalData = g1 * d1 + g2 * d2;

  const bits = [];
  const push = (val, n) => { for (let i = n - 1; i >= 0; i--) bits.push((val >> i) & 1); };
  push(4, 4);                                   // modo byte
  push(bytes.length, ver < 10 ? 8 : 16);
  for (const b of bytes) push(b, 8);
  for (let i = 0; i < 4 && bits.length < totalData * 8; i++) bits.push(0);   // terminador
  while (bits.length % 8) bits.push(0);
  const dw = [];
  for (let i = 0; i < bits.length; i += 8) dw.push(parseInt(bits.slice(i, i + 8).join(''), 2));
  const PAD = [0xEC, 0x11];
  for (let i = 0; dw.length < totalData; i++) dw.push(PAD[i % 2]);

  const blocos = [], ecs = [];
  let off = 0;
  for (let i = 0; i < g1 + g2; i++) {
    const len = i < g1 ? d1 : d2;
    const b = dw.slice(off, off + len); off += len;
    blocos.push(b); ecs.push(rsEnc(b, ecn));
  }
  const seq = [];
  for (let i = 0; i < Math.max(d1, d2); i++) for (const b of blocos) if (i < b.length) seq.push(b[i]);
  for (let i = 0; i < ecn; i++) for (const e of ecs) seq.push(e[i]);

  const m = Array.from({length: size}, () => new Array(size).fill(null));
  const setF = (r, c, val) => { if (r >= 0 && r < size && c >= 0 && c < size) m[r][c] = val; };
  const finder = (r, c) => { for (let i = -1; i <= 7; i++) for (let j = -1; j <= 7; j++) {
      const ii = r + i, jj = c + j; if (ii < 0 || jj < 0 || ii >= size || jj >= size) continue;
      const dark = (i >= 0 && i <= 6 && (j === 0 || j === 6)) || (j >= 0 && j <= 6 && (i === 0 || i === 6))
                 || (i >= 2 && i <= 4 && j >= 2 && j <= 4);
      setF(ii, jj, dark); } };
  finder(0, 0); finder(0, size - 7); finder(size - 7, 0);
  for (let i = 8; i < size - 8; i++) { setF(6, i, i % 2 === 0); setF(i, 6, i % 2 === 0); }
  const al = QR_ALIGN[v];
  for (const r of al) for (const c of al) {
    if ((r <= 8 && c <= 8) || (r <= 8 && c >= size - 9) || (r >= size - 9 && c <= 8)) continue;
    for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++)
      setF(r + i, c + j, Math.max(Math.abs(i), Math.abs(j)) !== 1); }
  setF(size - 8, 8, true);                        // modulo escuro fixo
  for (let i = 0; i < 9; i++) { if (m[8][i] === null) m[8][i] = false; if (m[i][8] === null) m[i][8] = false; }
  for (let i = 0; i < 8; i++) { if (m[8][size - 1 - i] === null) m[8][size - 1 - i] = false;
                                if (m[size - 1 - i][8] === null) m[size - 1 - i][8] = false; }
  if (ver >= 7) for (let i = 0; i < 18; i++) { const r = Math.floor(i / 3), c = i % 3;
    m[size - 11 + c][r] = false; m[r][size - 11 + c] = false; }

  const reservado = m.map(r => r.map(x => x !== null));
  const dados = [];
  for (const b of seq) for (let i = 7; i >= 0; i--) dados.push((b >> i) & 1);
  let di = 0, up = true;
  for (let col = size - 1; col > 0; col -= 2) {
    if (col === 6) col--;
    for (let t = 0; t < size; t++) {
      const row = up ? size - 1 - t : t;
      for (const c of [col, col - 1]) if (!reservado[row][c]) {
        m[row][c] = di < dados.length ? dados[di++] === 1 : false; }
    }
    up = !up;
  }
  const maskFn = [ (r,c)=>(r+c)%2===0, (r,c)=>r%2===0, (r,c)=>c%3===0, (r,c)=>(r+c)%3===0,
    (r,c)=>(Math.floor(r/2)+Math.floor(c/3))%2===0, (r,c)=>((r*c)%2)+((r*c)%3)===0,
    (r,c)=>(((r*c)%2)+((r*c)%3))%2===0, (r,c)=>(((r+c)%2)+((r*c)%3))%2===0 ];

  function penal(g) {
    let p = 0, n = g.length;
    for (let i = 0; i < n; i++) for (const linha of [g[i], g.map(r => r[i])]) {
      let run = 1;
      for (let j = 1; j < n; j++) { if (linha[j] === linha[j - 1]) run++;
        else { if (run >= 5) p += 3 + (run - 5); run = 1; } }
      if (run >= 5) p += 3 + (run - 5);
    }
    for (let r = 0; r < n - 1; r++) for (let c = 0; c < n - 1; c++)
      if (g[r][c] === g[r][c+1] && g[r][c] === g[r+1][c] && g[r][c] === g[r+1][c+1]) p += 3;
    const pat = [true,false,true,true,true,false,true,false,false,false,false];
    const pat2 = [false,false,false,false,true,false,true,true,true,false,true];
    for (let r = 0; r < n; r++) for (let c = 0; c + 10 < n; c++) {
      const h = g[r].slice(c, c + 11), vv = g.slice(c, c + 11).map(x => x[r]);
      if (pat.every((b, k) => b === h[k]) || pat2.every((b, k) => b === h[k])) p += 40;
      if (pat.every((b, k) => b === vv[k]) || pat2.every((b, k) => b === vv[k])) p += 40;
    }
    let dark = 0; for (const row of g) for (const x of row) if (x) dark++;
    p += Math.floor(Math.abs(dark * 100 / (n * n) - 50) / 5) * 10;
    return p;
  }

  let melhor = null, melhorP = Infinity, melhorMask = 0;
  for (let k = 0; k < 8; k++) {
    const g = m.map((row, r) => row.map((x, c) => reservado[r][c] ? x : (maskFn[k](r, c) ? !x : x)));
    const fmt = bch15((0 << 3) | k);              // 00 = nivel M
    for (let i = 0; i < 15; i++) {
      const b = ((fmt >> i) & 1) === 1;
      // copia vertical, coluna 8
      if (i < 6) g[i][8] = b; else if (i < 8) g[i + 1][8] = b; else g[size - 15 + i][8] = b;
      // copia horizontal, linha 8
      if (i < 8) g[8][size - 1 - i] = b; else if (i === 8) g[8][7] = b; else g[8][14 - i] = b;
    }
    g[size - 8][8] = true;
    if (ver >= 7) { const vi = bch18(ver);
      for (let i = 0; i < 18; i++) { const b = ((vi >> i) & 1) === 1;
        g[Math.floor(i / 3)][size - 11 + (i % 3)] = b; g[size - 11 + (i % 3)][Math.floor(i / 3)] = b; } }
    const pen = penal(g);
    if (pen < melhorP) { melhorP = pen; melhor = g; melhorMask = k; }
  }
  return {matrix: melhor.map(r => r.map(Boolean)), version: ver, size, mask: melhorMask};
}
function qrSvg(texto, px = 240, quiet = 4) {
  const {matrix, size} = qrMatrix(texto);
  const total = size + quiet * 2, s = px / total;
  let d = '';
  for (let r = 0; r < size; r++) for (let c = 0; c < size; c++) if (matrix[r][c])
    d += `M${((c + quiet) * s).toFixed(3)} ${((r + quiet) * s).toFixed(3)}h${s.toFixed(3)}v${s.toFixed(3)}h-${s.toFixed(3)}z`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${px} ${px}" width="${px}" height="${px}" role="img">`
       + `<rect width="${px}" height="${px}" fill="#ffffff"/><path d="${d}" fill="#000000"/></svg>`;
}


/* ======== js/core2.js ======== */
/* ============================================================================
   Núcleo numérico v2 do Laboratório de Decisão de Crédito.
   Mudança principal: UM único avaliador de carteira produz o registro por
   operação, e todo agregado (resumo, curva, composição, esperado, realizado,
   ponte de reconciliação) consome exatamente os mesmos registros.
   ========================================================================= */
const EPS=1e-15;
const clip=(p,lo=EPS,hi=1-EPS)=>Math.min(hi,Math.max(lo,p));
const sigmoid=z=>1/(1+Math.exp(-z));
const logit=p=>Math.log(clip(p)/(1-clip(p)));

/* ---------- ordenação e discriminação ---------- */
function auc(y,p){
  const n=y.length;let np_=0,nn=0;
  for(let i=0;i<n;i++)(y[i]===1?np_++:nn++);
  if(!np_||!nn)return null;
  const idx=Array.from({length:n},(_,i)=>i).sort((a,b)=>p[a]-p[b]);
  const r=new Float64Array(n);let i=0;
  while(i<n){let j=i;while(j+1<n&&p[idx[j+1]]===p[idx[i]])j++;
    const rk=(i+j+2)/2;for(let k=i;k<=j;k++)r[idx[k]]=rk;i=j+1;}
  let s=0;for(let k=0;k<n;k++)if(y[k]===1)s+=r[k];
  return (s-np_*(np_+1)/2)/(np_*nn);
}
/* contagem explícita de pares, para a página que ensina o que a AUC conta */
function paresAUC(y,p){
  const pos=[],neg=[];
  for(let i=0;i<y.length;i++)(y[i]===1?pos:neg).push(p[i]);
  let certos=0,empates=0,errados=0;const lista=[];
  for(const a of pos)for(const b of neg){
    const r=a>b?'certo':a===b?'empate':'errado';
    if(r==='certo')certos++;else if(r==='empate')empates++;else errados++;
    lista.push({mau:a,bom:b,r});}
  const tot=pos.length*neg.length;
  return {certos,empates,errados,total:tot,auc:tot?(certos+0.5*empates)/tot:null,lista};
}
function ks(y,p){
  const n=y.length;let np_=0,nn=0;
  for(let i=0;i<n;i++)(y[i]===1?np_++:nn++);
  if(!np_||!nn)return null;
  const idx=Array.from({length:n},(_,i)=>i).sort((a,b)=>p[a]-p[b]);
  let cb=0,cm=0,best=0,corte=null;
  for(let k=0;k<n;k++){const i=idx[k];(y[i]===1?cm++:cb++);
    if(k+1<n&&p[idx[k+1]]===p[i])continue;
    const d=Math.abs(cm/np_-cb/nn);
    if(d>best){best=d;corte=p[i];}}
  return {ks:best,corte};
}
function ksNoCorte(y,p,corte){
  let np_=0,nn=0,cm=0,cb=0;
  for(let i=0;i<y.length;i++){
    if(y[i]===1){np_++;if(p[i]<=corte)cm++;}else{nn++;if(p[i]<=corte)cb++;}}
  if(!np_||!nn)return null;
  return Math.abs(cm/np_-cb/nn);
}
const brier=(y,p)=>{let s=0;for(let i=0;i<y.length;i++)s+=(p[i]-y[i])**2;return s/y.length;};
const logloss=(y,p)=>{let s=0;
  for(let i=0;i<y.length;i++){const q=clip(p[i]);s+=y[i]*Math.log(q)+(1-y[i])*Math.log(1-q);}
  return -s/y.length;};
function gains(y,p,k=10){
  const n=y.length,idx=Array.from({length:n},(_,i)=>i).sort((a,b)=>p[b]-p[a]);
  const tot=y.reduce((a,b)=>a+b,0);const out=[];let acc=0,c=0;
  for(let q=1;q<=k;q++){const lim=Math.round(n*q/k);
    while(c<lim){acc+=y[idx[c]];c++;}
    const g=tot?acc/tot:null;
    out.push({pct:q/k,gains:g,lift:g===null?null:g/(q/k),n:lim,capturados:acc,total:tot});}
  return out;
}
/* ---------- proporções: Wilson, não aproximação normal ---------- */
function wilson(k,n,z=1.96){
  if(!n)return{p:null,lo:null,hi:null,n:0,k:0};
  const p=k/n,d=1+z*z/n,c=(p+z*z/(2*n))/d;
  const h=(z/d)*Math.sqrt(p*(1-p)/n+z*z/(4*n*n));
  return {p,lo:Math.max(c-h,0),hi:Math.min(c+h,1),n,k};
}
/* diferença entre duas proporções independentes, com erro padrão.
   Sobreposição de intervalos individuais NÃO é teste de diferença.        */
function difProporcoes(k1,n1,k2,n2){
  if(!n1||!n2)return null;
  const p1=k1/n1,p2=k2/n2,d=p1-p2;
  const se=Math.sqrt(p1*(1-p1)/n1+p2*(1-p2)/n2);
  return {dif:d,se,lo:d-1.96*se,hi:d+1.96*se,
    z:se>0?d/se:null,p1,p2,n1,n2};
}
function calibracao(y,p,k=10){
  const idx=Array.from({length:y.length},(_,i)=>i).sort((a,b)=>p[a]-p[b]);
  const out=[];
  for(let j=0;j<k;j++){
    const a=Math.floor(y.length*j/k),b=Math.floor(y.length*(j+1)/k);
    if(b<=a)continue;
    let sp=0,sy=0;
    for(let t=a;t<b;t++){sp+=p[idx[t]];sy+=y[idx[t]];}
    const w=wilson(sy,b-a);
    out.push({prev:sp/(b-a),obs:w.p,n:b-a,k:sy,lo:w.lo,hi:w.hi});}
  return out;
}
/* ---------- estabilidade ---------- */
function hist(v,edges){
  const c=new Float64Array(edges.length+1);
  for(const x of v){let b=0;while(b<edges.length&&x>edges[b])b++;c[b]++;}
  return Array.from(c,x=>x/v.length);
}
function psiFrom(pRef,qCur){
  const PISO=1e-4;
  let p=pRef.map(x=>x===0?PISO:x),q=qCur.map(x=>x===0?PISO:x);
  const sp=p.reduce((a,b)=>a+b,0),sq=q.reduce((a,b)=>a+b,0);
  p=p.map(x=>x/sp);q=q.map(x=>x/sq);
  let s=0;const parts=[];
  for(let j=0;j<p.length;j++){const t=(q[j]-p[j])*Math.log(q[j]/p[j]);parts.push(t);s+=t;}
  return {psi:s,parts,p,q};
}
const psi=(ref,cur,edges)=>psiFrom(hist(ref,edges),hist(cur,edges));
function woeIv(bons,maus){
  const tb=bons.reduce((a,b)=>a+b,0),tm=maus.reduce((a,b)=>a+b,0);
  const rows=[];let iv=0;
  for(let j=0;j<bons.length;j++){
    const pb=bons[j]/tb,pm=maus[j]/tm;
    if(!pb||!pm){rows.push({pb,pm,woe:null,iv:null});continue;}
    const w=Math.log(pb/pm),c=(pb-pm)*w;iv+=c;rows.push({pb,pm,woe:w,iv:c});}
  return {rows,iv};
}
/* ---------- ruído determinístico, para a revisão manual ser reprodutível ---------- */
function ruidoEstavel(id,semente=7){
  let h=(id*2654435761+semente*40503)>>>0;
  h^=h>>>15;h=Math.imul(h,2246822507)>>>0;h^=h>>>13;
  h=Math.imul(h,3266489909)>>>0;h^=h>>>16;
  const u1=Math.max((h>>>0)/4294967296,1e-9);
  let h2=Math.imul(h^0x9e3779b9,2654435761)>>>0;
  const u2=(h2>>>0)/4294967296;
  return Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2);   // normal padrão
}

/* ============================================================================
   AVALIADOR ÚNICO DE CARTEIRA
   ops: {id[], pd[], ead[], y[], pdTrue[]}
   par: corte, corteRev, capacidadeRevisao, qualidadeRevisao (0 a 1),
        lgd, taxaReceita, custoFunding, custoOper, custoCapital, custoRevisao
   Convenções, todas declaradas na página:
     R = ead*taxaReceita          receita monetária no horizonte SE não houver default
     F = ead*custoFunding         incorrido independentemente do default
     O = custoOper                incorrido por operação aprovada
     K = ead*custoCapital         custo econômico de capital, zero por padrão
     EL = pd_usada*lgd*ead        perda esperada, entra UMA única vez
     esperado = (1-pd)*R - EL - F - O - K
     realizado usa o desfecho observado, não a PD
   A revisão manual observa um sinal ruidoso da PD verdadeira. A qualidade do
   sinal é PARÂMETRO do exercício, não estimativa empírica.
   ========================================================================= */
function avaliaCarteira(ops,par){
  const {pd,ead,y,pdTrue}=ops;
  const n=pd.length;
  const P={corte:0.12,corteRev:0.22,capacidadeRevisao:0,qualidadeRevisao:0.6,
    lgd:0.65,taxaReceita:0.28,custoFunding:0.12,custoOper:120,custoCapital:0,
    custoRevisao:90,...par};
  /* 1. zona de cada operação, apenas pela PD do modelo */
  const reg=new Array(n);
  const fila=[];
  for(let i=0;i<n;i++){
    let zona;
    if(pd[i]<=P.corte)zona='auto';
    else if(pd[i]<=P.corteRev)zona='revisao';
    else zona='recusa';
    reg[i]={id:ops.id?ops.id[i]:i,pd:pd[i],ead:ead[i],y:y?y[i]:null,zona,
      pdTrue:pdTrue?pdTrue[i]:null,
      revisado:false,pdUsada:pd[i],aprovado:zona==='auto'};
    if(zona==='revisao')fila.push(i);
  }
  /* 2. fila de revisão: capacidade limitada, atende primeiro o menos arriscado.
        Quem fica fora da capacidade NÃO é revisado e é recusado.            */
  fila.sort((a,b)=>pd[a]-pd[b]);
  const atendidos=fila.slice(0,Math.min(P.capacidadeRevisao,fila.length));
  for(const i of atendidos){
    const w=Math.min(Math.max(P.qualidadeRevisao,0),1);
    const alvo=pdTrue&&pdTrue[i]!==undefined?pdTrue[i]:pd[i];
    const z=(1-w)*logit(pd[i])+w*logit(alvo)+ruidoEstavel(reg[i].id)*0.6*(1-w);
    reg[i].revisado=true;
    reg[i].pdRevisada=sigmoid(z);
    reg[i].pdUsada=reg[i].pdRevisada;
    reg[i].aprovado=reg[i].pdRevisada<=P.corte;
  }
  /* 3. componentes monetários, sempre dos MESMOS registros */
  for(const r of reg){
    r.custoRevisao=r.revisado?P.custoRevisao:0;
    if(!r.aprovado){r.R=0;r.F=0;r.O=0;r.K=0;r.EL=0;r.esperado=0;r.realizado=0;
      r.esperadoVerdadeiro=0;continue;}
    r.R=r.ead*P.taxaReceita; r.F=r.ead*P.custoFunding; r.O=P.custoOper; r.K=r.ead*P.custoCapital;
    r.EL=r.pdUsada*P.lgd*r.ead;
    r.esperado=(1-r.pdUsada)*r.R-r.EL-r.F-r.O-r.K;
    /* valor da decisão sob a PD verdadeira do gerador. Só existe porque a base
       é sintética; num banco real esta coluna não é observável.               */
    r.esperadoVerdadeiro=r.pdTrue===null?null:
      (1-r.pdTrue)*r.R-r.pdTrue*P.lgd*r.ead-r.F-r.O-r.K;
    r.realizado=r.y===null?null:(r.y?(-P.lgd*r.ead-r.F-r.O-r.K):(r.R-r.F-r.O-r.K));
  }
  /* 4. agregados, todos derivados de reg */
  const ap=reg.filter(r=>r.aprovado);
  const sum=(a,f)=>a.reduce((s,r)=>s+f(r),0);
  const custoRev=sum(reg,r=>r.custoRevisao);
  const receita=sum(ap,r=>r.R),el=sum(ap,r=>r.EL),fund=sum(ap,r=>r.F);
  const oper=sum(ap,r=>r.O),cap=sum(ap,r=>r.K);
  const receitaEsp=sum(ap,r=>(1-r.pdUsada)*r.R);
  const esperado=sum(ap,r=>r.esperado)-custoRev;
  const realizado=ap.some(r=>r.realizado===null)?null:sum(ap,r=>r.realizado)-custoRev;
  const esperadoVerdadeiro=ap.some(r=>r.esperadoVerdadeiro===null)?null
    :sum(ap,r=>r.esperadoVerdadeiro)-custoRev;
  return {registros:reg,aprovados:ap,par:P,
    n,nAprov:ap.length,nRevisados:reg.filter(r=>r.revisado).length,
    nRevAprov:reg.filter(r=>r.revisado&&r.aprovado).length,
    nFilaNaoAtendida:fila.length-atendidos.length,
    nRecusa:reg.filter(r=>!r.aprovado).length,
    exposicao:sum(ap,r=>r.ead),
    receitaBruta:receita,receitaEsperada:receitaEsp,el,funding:fund,oper,capital:cap,
    custoRevisao:custoRev,esperado,realizado,esperadoVerdadeiro,
    defaultsRealizados:y?sum(ap,r=>r.y):null,
    pdMedia:ap.length?sum(ap,r=>r.pdUsada)/ap.length:null,
    taxaAprov:n?ap.length/n:null,
    elSobreExp:sum(ap,r=>r.ead)?el/sum(ap,r=>r.ead):null,
    margemMedia:ap.length?esperado/ap.length:null};
}
/* ponte de reconciliação: as parcelas têm que somar o resultado, sem folga */
function ponte(res){
  const linhas=[
    {r:'Receita esperada, ponderada por não default',v:res.receitaEsperada},
    {r:'Perda esperada',v:-res.el},
    {r:'Custo de funding',v:-res.funding},
    {r:'Custo operacional',v:-res.oper},
    {r:'Custo de capital',v:-res.capital},
    {r:'Custo das revisões',v:-res.custoRevisao}];
  const soma=linhas.reduce((s,l)=>s+l.v,0);
  return {linhas,soma,resultado:res.esperado,fecha:Math.abs(soma-res.esperado)<1e-6};
}


/* ======== js/nucleo_did.js ======== */
/* ============================================================================
   Núcleo didático: árvore, logit e boosting recalculados no navegador.
   Toda função aqui é conferida contra scikit-learn no relatório de validação.
   ========================================================================== */
const gini=y=>{if(!y.length)return 0;const p=y.reduce((a,b)=>a+b,0)/y.length;return 2*p*(1-p);};
const entropia=y=>{if(!y.length)return 0;const p=y.reduce((a,b)=>a+b,0)/y.length;
  if(p===0||p===1)return 0;return -(p*Math.log2(p)+(1-p)*Math.log2(1-p));};

/* candidatos de corte: pontos médios entre valores vizinhos distintos */
function cortesCandidatos(x){
  const v=[...new Set(x)].sort((a,b)=>a-b);const c=[];
  for(let i=0;i<v.length-1;i++)c.push((v[i]+v[i+1])/2);
  return c;
}
/* avalia UMA divisão: composição dos dois grupos e ganho no critério */
function avaliaCorte(x,y,corte,crit=gini){
  const ie=[],id=[];
  for(let i=0;i<x.length;i++)(x[i]<=corte?ie:id).push(i);
  if(!ie.length||!id.length)return null;
  const ye=ie.map(i=>y[i]),yd=id.map(i=>y[i]),n=y.length;
  const antes=crit(y),ce=crit(ye),cd=crit(yd);
  const depois=(ye.length/n)*ce+(yd.length/n)*cd;
  return {corte,idxEsq:ie,idxDir:id,nEsq:ye.length,nDir:yd.length,
    dEsq:ye.reduce((a,b)=>a+b,0),dDir:yd.reduce((a,b)=>a+b,0),
    antes,critEsq:ce,critDir:cd,depois,ganho:antes-depois,
    pEsq:ye.reduce((a,b)=>a+b,0)/ye.length,pDir:yd.reduce((a,b)=>a+b,0)/yd.length};
}
/* busca exaustiva do melhor corte de UMA variável */
function melhorCorte(x,y,crit=gini){
  let melhor=null;
  for(const c of cortesCandidatos(x)){
    const a=avaliaCorte(x,y,c,crit);
    if(a&&(!melhor||a.ganho>melhor.ganho))melhor=a;}
  return melhor;
}
/* busca em TODAS as variáveis: é assim que a árvore escolhe a divisão */
function melhorDivisao(vars,y,crit=gini){
  let melhor=null;
  for(const v of vars){
    const m=melhorCorte(v.x,y,crit);
    if(m&&(!melhor||m.ganho>melhor.ganho))melhor={...m,variavel:v.nome,unidade:v.unidade};}
  return melhor;
}
/* árvore de classificação por busca gulosa, com limites explícitos */
function arvoreClassificacao(vars,y,{prof=2,minFolha=2,minGanho=1e-9}={}){
  const idxTodos=y.map((_,i)=>i);
  function no(idx,d){
    const ys=idx.map(i=>y[i]);
    const base={idx,n:idx.length,d:ys.reduce((a,b)=>a+b,0),
      p:ys.reduce((a,b)=>a+b,0)/idx.length,gini:gini(ys)};
    if(d===0||idx.length<2*minFolha||base.d===0||base.d===idx.length)
      return {...base,tipo:'folha'};
    const sub=vars.map(v=>({...v,x:idx.map(i=>v.x[i])}));
    const m=melhorDivisao(sub,ys);
    if(!m||m.ganho<minGanho||m.nEsq<minFolha||m.nDir<minFolha)return {...base,tipo:'folha'};
    return {...base,tipo:'no',variavel:m.variavel,corte:m.corte,ganho:m.ganho,unidade:m.unidade,
      esq:no(m.idxEsq.map(i=>idx[i]),d-1),dir:no(m.idxDir.map(i=>idx[i]),d-1)};
  }
  return no(idxTodos,prof);
}
function caminhoNaArvore(no,xs,trilha=[]){
  if(no.tipo==='folha')return {folha:no,trilha};
  const v=xs[no.variavel],vai=v<=no.corte,destino=vai?no.esq:no.dir;
  trilha.push({variavel:no.variavel,corte:no.corte,valor:v,vai:vai?'esq':'dir',
    unidade:no.unidade,n:no.n,destino});
  return caminhoNaArvore(destino,xs,trilha);
}
function folhasDaArvore(no,acc=[]){
  if(no.tipo==='folha'){acc.push(no);return acc;}
  folhasDaArvore(no.esq,acc);folhasDaArvore(no.dir,acc);return acc;
}

/* ---------------- logit por descida de gradiente, passo a passo ---------------- */
function passoLogit(X,y,b,lr){
  const n=y.length,k=b.length-1;
  const p=X.map(r=>{let z=b[0];for(let j=0;j<k;j++)z+=b[j+1]*r[j];return 1/(1+Math.exp(-z));});
  let perda=0;for(let i=0;i<n;i++){
    const q=Math.min(Math.max(p[i],1e-12),1-1e-12);
    perda-=y[i]*Math.log(q)+(1-y[i])*Math.log(1-q);}
  perda/=n;
  const g=new Array(k+1).fill(0);
  for(let i=0;i<n;i++){const e=p[i]-y[i];g[0]+=e;for(let j=0;j<k;j++)g[j+1]+=e*X[i][j];}
  for(let j=0;j<=k;j++)g[j]/=n;
  return {p,perda,grad:g,novo:b.map((v,j)=>v-lr*g[j])};
}
function ajustaLogit(X,y,{lr=0.10,iter=20000,b0=null}={}){
  let b=b0||new Array(X[0].length+1).fill(0);const hist=[];
  for(let t=0;t<iter;t++){
    const s=passoLogit(X,y,b,lr);
    if(t<4||t===5||t===10||t===25||t===50||t===100||t===250||t===500||t===1000||t===2500||t===iter-1)
      hist.push({it:t,b:[...b],perda:s.perda,grad:s.grad});
    b=s.novo;}
  const f=passoLogit(X,y,b,0);
  hist.push({it:iter,b:[...b],perda:f.perda,grad:f.grad});
  return {beta:b,hist,p:f.p,perda:f.perda};
}

/* ---------------- boosting: mesma mecânica das duas demonstrações ---------------- */
/* árvore de regressão por mínimos quadrados sobre o alvo corrente (resíduo ou gradiente) */
function arvoreRegressao(vars,alvo,{prof=1,minFolha=2}={}){
  function no(idx,d){
    const a=idx.map(i=>alvo[i]),media=a.reduce((s,v)=>s+v,0)/a.length;
    if(d===0||idx.length<2*minFolha)
      return {tipo:'folha',valor:media,n:idx.length,idx};
    let melhor=null;
    for(const v of vars){
      const xs=idx.map(i=>v.x[i]);
      for(const c of cortesCandidatos(xs)){
        const ie=[],id=[];
        idx.forEach(i=>(v.x[i]<=c?ie:id).push(i));
        if(ie.length<minFolha||id.length<minFolha)continue;
        const me=ie.reduce((s,i)=>s+alvo[i],0)/ie.length;
        const md=id.reduce((s,i)=>s+alvo[i],0)/id.length;
        const sse=ie.reduce((s,i)=>s+(alvo[i]-me)**2,0)+id.reduce((s,i)=>s+(alvo[i]-md)**2,0);
        if(!melhor||sse<melhor.sse)melhor={variavel:v.nome,corte:c,sse,ie,id,me,md,unidade:v.unidade};}}
    if(!melhor)return {tipo:'folha',valor:media,n:idx.length,idx};
    return {tipo:'no',variavel:melhor.variavel,corte:melhor.corte,unidade:melhor.unidade,
      n:idx.length,sse:melhor.sse,esq:no(melhor.ie,d-1),dir:no(melhor.id,d-1)};
  }
  return no(alvo.map((_,i)=>i),prof);
}
function aplicaRegressao(no,vars,i){
  if(no.tipo==='folha')return no.valor;
  const v=vars.find(v=>v.nome===no.variavel);
  return aplicaRegressao(v.x[i]<=no.corte?no.esq:no.dir,vars,i);
}
/* boosting para erro quadrático: resíduo É o negativo do gradiente */
function boostingRegressao(vars,y,{eta=0.5,M=4,prof=1,minFolha=1}={}){
  const n=y.length,media=y.reduce((a,b)=>a+b,0)/n;
  let F=new Array(n).fill(media);
  const passos=[{m:0,F:[...F],res:y.map((v,i)=>v-F[i]),
    mse:y.reduce((s,v,i)=>s+(v-F[i])**2,0)/n,arvore:null,h:null}];
  for(let m=1;m<=M;m++){
    const r=y.map((v,i)=>v-F[i]);
    const arv=arvoreRegressao(vars,r,{prof,minFolha});
    const h=y.map((_,i)=>aplicaRegressao(arv,vars,i));
    F=F.map((v,i)=>v+eta*h[i]);
    passos.push({m,F:[...F],res:r,h,arvore:arv,
      mse:y.reduce((s,v,i)=>s+(v-F[i])**2,0)/n});}
  return passos;
}
/* boosting para log loss: o negativo do gradiente no ESCORE é y menos p */
function boostingClassificacao(vars,y,{eta=0.4,M=4,prof=2,minFolha=2}={}){
  const n=y.length,p0=y.reduce((a,b)=>a+b,0)/n,F0=Math.log(p0/(1-p0));
  let F=new Array(n).fill(F0);
  const prob=()=>F.map(v=>1/(1+Math.exp(-v)));
  const perdaDe=p=>{let s=0;for(let i=0;i<n;i++){
    const q=Math.min(Math.max(p[i],1e-12),1-1e-12);
    s-=y[i]*Math.log(q)+(1-y[i])*Math.log(1-q);}return s/n;};
  let p=prob();
  const passos=[{m:0,F:[...F],p:[...p],perda:perdaDe(p),grad:y.map((v,i)=>v-p[i]),arvore:null,h:null}];
  for(let m=1;m<=M;m++){
    p=prob();const g=y.map((v,i)=>v-p[i]);
    const arv=arvoreRegressao(vars,g,{prof,minFolha});
    const h=y.map((_,i)=>aplicaRegressao(arv,vars,i));
    F=F.map((v,i)=>v+eta*h[i]);
    const pn=prob();
    passos.push({m,F:[...F],p:[...pn],perda:perdaDe(pn),grad:g,h,arvore:arv});}
  return passos;
}


