P({id:'c2p16',cap:2,n:16,nivel:'essencial',t:{exp:2,ex:3,prat:2,disc:1},origem:'rec',
 titulo:'Toda estimativa vem com incerteza, e ela se calcula',
 aprendizado:'Uma proporção estimada tem intervalo, a largura depende do número de observações e não da fração, e reportar a proporção sem o intervalo esconde a informação decisiva.',
 apoio:'A mesma fração observada, um oitavo, com números de observações diferentes. Intervalo de Wilson a 95%.',
 visual:()=>`<div class="palcoflex"><div class="esq">
  <div class="ctrl"><label for="c216n">Observações no grupo, mantendo a fração de 1 em 8 <b id="c216nv"></b></label>
   <input type="range" id="c216n" min="8" max="800" step="8" value="8"></div>
  <div id="c216o" style="margin-top:10px"></div>
  <div class="formula" style="margin-top:10px">largura ≈ proporcional a 1 ÷ raiz de n</div>
  <p class="nota">Quadruplicar a amostra reduz a largura pela metade. Este é o motivo pelo qual folhas de
  árvore com poucos casos produzem PD sem significado, e é o motivo pelo qual o capítulo 7 exige intervalo
  em toda curva de calibração.</p>
  </div><div class="dir"><div class="svgfit" id="c216g"></div>
  <div class="revelacao" style="margin-top:10px"><h4>A folha de uma proposta, revisitada</h4>
  A árvore de profundidade 3 da página 14 criou uma folha com uma única proposta e PD zero.
  Com uma observação, o intervalo de Wilson a 95% vai de 0% a 79,3%. A folha não afirma nada.</div></div></div>`,
 init:()=>{const sl=document.getElementById('c216n');
  const upd=()=>{const n=+sl.value,k=Math.round(n/8);
   const w0=wilson(k,n),lo=w0.lo,hi=w0.hi;
   document.getElementById('c216nv').textContent=n+' observações, '+k+' default'+(k===1?'':'s');
   const casos=[{n:8,k:1},{n:80,k:10},{n:800,k:100},{n,k,atual:true}];
   document.getElementById('c216o').innerHTML=`<div class="painel">
    <div class="rot">Estimativa e intervalo</div>
    <div style="text-align:center;margin-top:6px"><div class="numg">${pct(k/n,1)}</div>
    <div class="nota">intervalo de 95%: de <b>${pct(lo,1)}</b> a <b>${pct(hi,1)}</b>,
    largura de ${pct(hi-lo,1)}</div></div>
    <div class="rolax" style="margin-top:10px"><table><thead><tr><th>Observações</th><th>Defaults</th>
     <th>Estimativa</th><th>Intervalo de 95%</th><th>Largura</th></tr></thead><tbody>
     ${casos.filter((c,i,a)=>a.findIndex(z=>z.n===c.n)===i).sort((a,b)=>a.n-b.n).map(c=>{
       const _w=wilson(c.k,c.n),a1=_w.lo,b1=_w.hi;
       return `<tr${c.atual?' style="background:#FBF3DE"':''}><th scope="row">${c.n}</th>
        <td class="num">${c.k}</td><td class="num">${pct(c.k/c.n,1)}</td>
        <td class="num">${pct(a1,1)} a ${pct(b1,1)}</td>
        <td class="num">${pct(b1-a1,1)}</td></tr>`;}).join('')}</tbody></table></div>
    <p class="nota" style="margin-top:7px">A estimativa pontual é sempre 12,5%. Só a largura muda.</p></div>`;
   const pts=[],lows=[],his=[];
   for(let m=8;m<=800;m+=8){const kk=Math.round(m/8),_w2=wilson(kk,m),a1=_w2.lo,b1=_w2.hi;
    pts.push([m,kk/m]);lows.push([m,a1]);his.push([m,b1]);}
   document.getElementById('c216g').innerHTML=chLinhas({
    series:[{nome:'limite superior do intervalo',pts:his,cor:COR.alerta,tracejada:true},
      {nome:'estimativa pontual',pts,cor:COR.ink},
      {nome:'limite inferior do intervalo',pts:lows,cor:COR.alerta,tracejada:true}],
    xMin:8,xMax:800,yMin:0,yMax:0.55,yTicks:[0,0.125,0.25,0.375,0.5],
    xTicks:[8,200,400,600,800].map(v=>({v,r:String(v)})),
    yTit:'PD estimada',xTit:'número de observações no grupo',yFmt:v=>pct(v,1),
    marcas:[{x:n,y:lo,cor:COR.aten,r0:5},{x:n,y:hi,cor:COR.aten,r0:5,r:'sua escolha'}],
    w:600,h:380});};
  sl.addEventListener('input',upd);upd();},
 conexao:'Resta o limite que nenhum tamanho de amostra resolve.',
 guia:undefined});

