/* ======== v3/22_cap4.js ======== */
/* ===================== CAPÍTULO 4: regressão logística =====================
   Probabilidade, odds e log odds são ensinados separadamente antes do modelo.
   Os coeficientes não são apresentados prontos: eles são aprendidos em tela,
   por minimização da perda, com o mesmo resultado do gerador em Python.
   ========================================================================= */
const BET=DID.logit.beta;                       // [-5,6666 ; 0,7453 ; 1,3955]
const zDe=(u,a,b=BET)=>b[0]+b[1]*(u/10)+b[2]*(a/10);
const pdDe=(u,a,b=BET)=>sigmoid(zDe(u,a,b));
const oddsDe=p=>p/(1-p);

