P({id:'c5p18',cap:5,n:18,nivel:'essencial',t:{exp:2,ex:2,prat:4,disc:2},origem:'rec',
 titulo:'Árvore contra logística, com os mesmos dados',
 aprendizado:'As duas famílias erram de maneiras diferentes, e a escolha entre elas depende do uso, não de superioridade geral.',
 apoio:'As dezesseis propostas, com a PD de cada família lado a lado, e a perda de cada uma.',
 visual:()=>{const linhas=BASE.map(r=>{
   const pl=pdDe(r.util,r.atraso);
   const pa=caminhoNaArvore(ARV2,{utilizacao:r.util,atraso:r.atraso}).folha.p;
   const paC=Math.min(Math.max(pa,0.02),0.98);
   return {...r,pl,pa,paC,ll:r.y?-Math.log(pl):-Math.log(1-pl),la:r.y?-Math.log(paC):-Math.log(1-paC)};});
  const perdaL=linhas.reduce((s,l)=>s+l.ll,0)/linhas.length;
  const perdaA=linhas.reduce((s,l)=>s+l.la,0)/linhas.length;
  return `<div class="palcoflex"><div class="esq"><div class="rot">Maiores discordâncias na tela</div><div class="rolax resumo-tabela"><table>
   <thead><tr><th>#</th><th>Util.</th><th>Atraso</th><th>y</th><th>Logística</th><th>Árvore</th>
    <th>Diferença</th></tr></thead><tbody>
   ${linhas.map(l=>`<tr${Math.abs(l.pl-l.pa)>0.35?' style="background:#F7E6E6"':' class="linha-detalhe"'}>
    <th scope="row">#${l.id}</th><td class="num">${l.util}%</td><td class="num">${l.atraso} d</td>
    <td class="num" style="color:${l.y?COR.alerta:COR.ok};font-weight:700">${l.y}</td>
    <td class="num">${pct(l.pl,1)}</td><td class="num">${pct(l.pa,0)}</td>
    <td class="num">${n2(100*(l.pa-l.pl),1)} pp</td></tr>`).join('')}
   </tbody></table></div>
   <p class="nota" style="margin-top:8px">Linhas em rosa: discordância acima de 35 pontos de PD.
   A árvore foi avaliada com piso e teto de 2% e 98% na perda, porque folhas puras produziriam perda
   infinita. ${selo('rec')}</p>
   </div><div class="dir"><div class="grade g2">
   <div class="painel" style="text-align:center"><div class="rot">Log loss da logística</div>
    <div class="numg">${n2(perdaL,5)}</div></div>
   <div class="painel" style="text-align:center"><div class="rot">Log loss da árvore</div>
    <div class="numg">${n2(perdaA,5)}</div></div></div>
   <div class="revelacao ruim" style="margin-top:10px"><h4>Este número não decide nada</h4>
   As duas perdas são calculadas na mesma amostra em que os dois modelos foram estimados. O capítulo 2
   já mostrou que essa comparação é vazia. Com dezesseis propostas não existe amostra separada possível,
   e por isso a comparação de verdade acontece no capítulo 7, na base de 5.000, com teste estatístico.</div>
   <div class="painel" style="margin-top:10px"><div class="rot">O que cada família entrega</div>
   <table style="margin-top:7px"><thead><tr><th></th><th>Logística</th><th>Árvore</th></tr></thead><tbody>
   <tr><th scope="row">Fronteira</th><td>reta</td><td>escalonada</td></tr>
   <tr><th scope="row">Interação</th><td>só se escrita</td><td>automática</td></tr>
   <tr><th scope="row">PD</th><td>contínua</td><td>constante por região</td></tr>
   <tr><th scope="row">Explicação individual</th><td>contribuições somadas</td><td>caminho de regras</td></tr>
   <tr><th scope="row">Estabilidade</th><td>alta</td><td>baixa</td></tr>
   <tr><th scope="row">Extrapolação</th><td>continua a reta</td><td>repete a folha da borda</td></tr></tbody></table></div></div></div>`;},
 conexao:'Se a árvore é instável e a logística é rígida, existe uma terceira via.',
 guia:undefined});

