/* ======== v3/26_cap8.js ======== */
/* ============== CAPÍTULO 8: da previsão à decisão econômica ==============
   Regra do capítulo: todo agregado monetário sai de avaliaCarteira e toda tela
   que mostra totais fecha pela função ponte. Não existe segundo caminho de
   cálculo para nenhum número desta aula, nem para a operação isolada, que é
   avaliada pelo mesmo motor com uma única linha.
   ====================================================================== */
const C8PAR={lgd:0.65,taxaReceita:0.28,custoFunding:0.12,custoOper:120,
  custoCapital:0.02,custoRevisao:90};
const C8EAD=10000;
const C8OPS={id:DADOS.oot.y.map((_,i)=>i),pd:DADOS.oot.pl,ead:DADOS.oot.ead,
  y:DADOS.oot.y,pdTrue:DADOS.oot.pt};
const C8N=C8OPS.pd.length, C8D=C8OPS.y.reduce((s,v)=>s+v,0);

/* uma operação, ou poucas, avaliadas pelo MESMO motor da carteira.
   Sem y e sem pdTrue: realizado e valor verdadeiro ficam nulos e não são
   exibidos nestas páginas, porque uma operação hipotética não tem desfecho. */
const c8uma=(pds,eads,par={})=>avaliaCarteira({id:pds.map((_,i)=>i),pd:pds,ead:eads},
  {corte:1,corteRev:1,capacidadeRevisao:0,...C8PAR,...par});

/* perda no default, obtida do motor fazendo a PD valer 1 */
const c8perdaNoDefault=(ead,par={})=>c8uma([1],[ead],par).el;

/* ponto de equilíbrio em PD, solução explícita da equação de resultado */
const c8eq=(ead,par={})=>{const P={...C8PAR,...par};
  return (ead*(P.taxaReceita-P.custoFunding-P.custoCapital)-P.custoOper)
        /(ead*(P.taxaReceita+P.lgd));};

/* carteira inteira aprovada, registro por operação. É daqui que saem as
   parcelas de qualquer operação recusada por um corte mais apertado. */
const C8TODAS=avaliaCarteira(C8OPS,{corte:1,corteRev:1,capacidadeRevisao:0,...C8PAR});

/* choque de PD aplicado em log odds, sobre a PD do modelo e sobre a PD
   verdadeira do gerador. O desfecho observado é do passado e não é deslocado. */
const c8choque=k=>k===0?C8OPS:{id:C8OPS.id,ead:C8OPS.ead,y:C8OPS.y,
  pd:C8OPS.pd.map(p=>sigmoid(logit(p)+k)),
  pdTrue:C8OPS.pdTrue.map(p=>sigmoid(logit(p)+k))};

/* curva de resultado esperado por corte, sempre pelo motor único */
const c8curva=(ops,par={},passo=5)=>{const pts=[];let melhor=null;
  for(let c=passo;c<=600;c+=passo){
    const r=avaliaCarteira(ops,{corte:c/1000,corteRev:c/1000,capacidadeRevisao:0,...C8PAR,...par});
    pts.push([c/1000,r.esperado]);
    if(!melhor||r.esperado>melhor.v)melhor={c:c/1000,v:r.esperado,n:r.nAprov};}
  return {pts,melhor};};
const C8CURVA=c8curva(C8OPS), C8OTIMO=C8CURVA.melhor;
const C8INTUI=0.10;

/* zero exibido é sempre zero, nunca zero negativo vindo de arredondamento */
const z0=v=>v===null||v===undefined?v:Math.abs(v)<0.5?0:v;

/* ponte de reconciliação renderizada. Único renderizador de totais do capítulo. */
function c8ponte(res,titulo){const b=ponte(res);
  return `<div class="painel"><h3>${esc(titulo||'Ponte de reconciliação')} ${selo('rec')}</h3>
   <div class="rolax"><table><tbody>
   ${b.linhas.map(l=>`<tr><th scope="row">${esc(l.r)}</th>
    <td class="num" style="color:${l.v<-0.5?'var(--alerta)':'var(--ok)'}">${rsk(z0(l.v))}</td></tr>`).join('')}
   <tr style="font-weight:700;background:#EFF3FA"><th scope="row">Resultado esperado</th>
    <td class="num">${rsk(z0(b.soma))}</td></tr></tbody></table></div>
   <div class="revelacao ${b.fecha?'bom':'ruim'}" style="margin-top:9px">
   ${b.fecha?`<b>As parcelas somam exatamente o resultado.</b> A folga entre a soma das parcelas e o
    total informado é de ${rs(z0(b.soma-b.resultado))}. Resumo, composição e curva desta aula leem os mesmos
    registros que produziram estas linhas.`
   :'<b>As parcelas não fecham.</b> Folga aqui significaria dois caminhos de cálculo para o mesmo número.'}
   </div></div>`;}

