P({id:'c8p5',cap:8,n:5,nivel:'essencial',t:{exp:4,ex:3,disc:2},origem:'sint',
 titulo:'A equação de resultado, construída um termo de cada vez',
 aprendizado:'O resultado esperado pondera a receita pelo ramo sem default, subtrai a perda esperada uma única vez e desconta funding, custo operacional e custo de capital, que ocorrem havendo default ou não.',
 apoio:'Cinco parcelas construídas separadamente e só então somadas, para que a contagem dupla da perda fique impossível de cometer.',
 visual:()=>{const pd=0.10,r=c8uma([pd],[C8EAD]).registros[0];
  const perda=c8perdaNoDefault(C8EAD);
  const sem=r.R-r.F-r.O-r.K, com=-perda-r.F-r.O-r.K;
  return `<div class="palcoflex"><div class="esq">
  <div class="painel"><div class="rot">Cada termo, isolado, para uma operação de exposição ${rs(C8EAD)} e PD de ${pct(pd,0)} ${selo('sint')}</div>
   <div class="rolax"><table style="margin-top:7px"><thead><tr><th>Termo</th><th>Como se forma</th>
    <th>Quando ocorre</th><th>Valor</th></tr></thead><tbody>
   <tr><th scope="row">R, receita</th><td>${pct(C8PAR.taxaReceita,0)} da exposição</td>
    <td>só se o cliente pagar</td><td class="num">${rs(r.R)}</td></tr>
   <tr><th scope="row">LGD × EAD, perda no default</th><td>${pct(C8PAR.lgd,0)} da exposição</td>
    <td>só se houver default</td><td class="num">${rs(perda)}</td></tr>
   <tr><th scope="row">F, funding</th><td>${pct(C8PAR.custoFunding,0)} da exposição</td>
    <td>sempre, o dinheiro foi captado</td><td class="num">${rs(r.F)}</td></tr>
   <tr><th scope="row">O, custo operacional</th><td>valor fixo por operação aprovada</td>
    <td>sempre, a proposta foi processada</td><td class="num">${rs(r.O)}</td></tr>
   <tr><th scope="row">K, custo de capital</th><td>${pct(C8PAR.custoCapital,0)} da exposição</td>
    <td>sempre, o capital ficou alocado</td><td class="num">${rs(r.K)}</td></tr></tbody></table></div></div>
  <div class="formula" style="margin-top:10px">Resultado = (1 − PD) × R − PD × LGD × EAD − F − O − K
 = ${pct(1-pd,0)} × ${rs(r.R)} − ${pct(pd,0)} × ${rs(perda)} − ${rs(r.F)} − ${rs(r.O)} − ${rs(r.K)}
 = ${rs(r.esperado)}</div>
  <div class="revelacao ruim" style="margin-top:10px"><h4>Os dois erros de contagem</h4>
  <b>Receita cheia.</b> Escrever receita inteira menos perda esperada menos custos dá
  ${rs(r.R-r.EL-r.F-r.O-r.K)} em vez de ${rs(r.esperado)}. A diferença de ${rs(pd*r.R)} é PD × R, a
  receita atribuída a um ramo em que o cliente não paga. O fator ${pct(1-pd,0)} existe exatamente para
  excluir essa parcela.
  <b style="display:block;margin-top:7px">Perda duas vezes.</b> Ponderar a receita por (1 − PD) e ainda
  descontar a perda esperada duas vezes, uma como provisão e outra como perda, dá
  ${rs(r.esperado-r.EL)}. A perda esperada entra uma única vez, e a ponte ao lado é o que impede os dois
  erros de passarem despercebidos num material de comitê.</div>
  </div><div class="dir">
  <div class="painel"><div class="rot">Os dois desfechos e a média ponderada</div>
   <div class="svgfit" style="margin-top:7px">${arvoreEconomica({pd,semDefault:sem,comDefault:com,
    esperado:r.esperado,larg:520})}</div>
   <p class="nota" style="margin-top:7px">No ramo de default não há receita. É por isso que a perda
   esperada entra uma única vez. Funding, operacional e capital aparecem nos dois ramos, porque não
   dependem do desfecho.</p></div>
  ${c8ponte(c8uma([pd],[C8EAD]),'As cinco parcelas somam o resultado, para uma operação só')}
  </div></div>`;},
 conexao:'Com a equação montada, existe uma PD em que ela cruza o zero.',
 guia:undefined});

/* =========================== página 6 =========================== */
const Q_C8P6Q={
 rot:'De quem é o ponto de equilíbrio',
 pergunta:'O ponto de equilíbrio de uma operação padrão desta aula é '+pct(c8eq(C8EAD),2)
  +'. Qual destes eventos move esse número, sem que o cliente tenha mudado em nada?',
 alt:['A PD estimada do cliente subir na reestimação do modelo',
      'O custo de captação subir de '+pct(C8PAR.custoFunding,0)+' para '+pct(0.18,0)+' da exposição',
      'O modelo ser reestimado com mais dados e ganhar AUC'],
 certa:undefined,
 porqueCerta:undefined,
 erros:undefined};

P({id:'c8p6',cap:8,n:6,nivel:'essencial',t:{exp:3,ex:2,prat:3,disc:1},origem:'sint',
 titulo:'O ponto de equilíbrio em PD sai de uma equação resolvida, não de um palpite',
 aprendizado:'Igualar o resultado esperado a zero e isolar a PD dá um limiar explícito, que pertence ao contrato econômico e não ao cliente.',
 apoio:'A derivação em quatro linhas, a conferência no motor econômico e o efeito de cada parâmetro sobre o limiar.',
 visual:()=>{const eq=c8eq(C8EAD),r=c8uma([eq],[C8EAD]);
  const reg=c8uma([0.10],[C8EAD]).registros[0];
  return `<div class="palcoflex"><div class="esq">
  <div class="painel"><div class="rot">A derivação, linha a linha</div>
   <div class="formula" style="margin-top:7px">(1 − PD) × R − PD × LGD × EAD − F − O − K = 0
R − PD × R − PD × LGD × EAD = F + O + K
PD × (R + LGD × EAD) = R − F − O − K
PD* = (R − F − O − K) ÷ (R + LGD × EAD)</div>
   <div class="formula" style="margin-top:8px">PD* = (${rs(reg.R)} − ${rs(reg.F)} − ${rs(reg.O)} − ${rs(reg.K)})
      ÷ (${rs(reg.R)} + ${rs(c8perdaNoDefault(C8EAD))})
    = ${pct(eq,2)}</div>
   <div class="revelacao bom" style="margin-top:9px"><h4>Conferência no motor</h4>
   Avaliada com PD igual a ${pct(eq,2)}, a operação devolve resultado esperado de
   <b>${rs(r.esperado)}</b>. A fórmula acima e o motor econômico chegam ao mesmo lugar, o que é o teste
   mínimo de que não existem dois caminhos de cálculo.</div></div>
  <div class="ctrl" style="margin-top:10px"><label for="c8p6p">PD da operação <b id="c8p6pv"></b></label>
   <input type="range" id="c8p6p" min="0" max="400" step="5" value="100"></div>
  <div id="c8p6o"></div>
  </div><div class="dir"><div class="svgfit" id="c8p6g"></div>
   <div class="painel" style="margin-top:10px"><div class="rot">O limiar muda com o contrato, não com o cliente</div>
    <div class="rolax"><table style="margin-top:7px"><thead><tr><th>Cenário</th><th>O que mudou</th>
     <th>Ponto de equilíbrio</th></tr></thead><tbody>
    <tr style="background:#EFF3FA"><th scope="row">Declarado nesta aula</th><td>nada</td>
     <td class="num">${pct(c8eq(C8EAD),2)}</td></tr>
    <tr><th scope="row">Captação mais cara</th><td>funding de ${pct(C8PAR.custoFunding,0)} para ${pct(0.18,0)}</td>
     <td class="num" style="color:var(--alerta)">${pct(c8eq(C8EAD,{custoFunding:0.18}),2)}</td></tr>
    <tr><th scope="row">Garantia exigida</th><td>fração perdida de ${pct(C8PAR.lgd,0)} para ${pct(0.40,0)}</td>
     <td class="num" style="color:var(--ok)">${pct(c8eq(C8EAD,{lgd:0.40}),2)}</td></tr>
    <tr><th scope="row">Preço maior</th><td>receita de ${pct(C8PAR.taxaReceita,0)} para ${pct(0.34,0)}</td>
     <td class="num" style="color:var(--ok)">${pct(c8eq(C8EAD,{taxaReceita:0.34}),2)}</td></tr>
    <tr><th scope="row">Operação pequena</th><td>exposição de ${rs(C8EAD)} para ${rs(2000)}</td>
     <td class="num" style="color:var(--alerta)">${pct(c8eq(2000),2)}</td></tr>
    <tr><th scope="row">Operação grande</th><td>exposição de ${rs(C8EAD)} para ${rs(60000)}</td>
     <td class="num">${pct(c8eq(60000),2)}</td></tr></tbody></table></div>
    <p class="nota" style="margin-top:8px">Nenhuma linha desta tabela mexe no cliente. Todas mexem no
    limiar. A última coluna é a razão pela qual um corte único em PD não serve a contratos diferentes,
    e o preço dessa simplificação é medido na página 12.</p></div>
   <div style="margin-top:11px">${questao('c8p6q',Q_C8P6Q)}</div></div></div>`;},
 init:()=>{ligaQuestao('c8p6q',Q_C8P6Q);
  const sl=document.getElementById('c8p6p'),eq=c8eq(C8EAD);
  const upd=()=>{const pd=+sl.value/1000,r=c8uma([pd],[C8EAD]);
   document.getElementById('c8p6pv').textContent=pct(pd,1);
   document.getElementById('c8p6o').innerHTML=`<div class="painel" style="text-align:center">
    <div class="rot">Resultado esperado da operação</div>
    <div class="numg" style="color:${r.esperado>=0?'var(--ok)':'var(--alerta)'}">${rs(r.esperado)}</div>
    <div class="nota">${r.esperado>=0?'a operação compensa':'a operação destrói valor'} sob os parâmetros declarados,
    com limiar em ${pct(eq,2)}</div></div>`;
   const pts=[];for(let t=0;t<=0.4001;t+=0.005)pts.push([t,c8uma([t],[C8EAD]).esperado]);
   document.getElementById('c8p6g').innerHTML=chLinhas({
    series:[{nome:'resultado esperado',pts,cor:COR.ink,larg:2.2}],
    xMin:0,xMax:0.4,yMin:-2600,yMax:1600,yTicks:[-2600,-1550,-500,550,1600],
    xTicks:[0,0.1,0.2,0.3,0.4].map(v=>({v,r:pct(v,0)})),
    yTit:'resultado esperado',xTit:'probabilidade de default',yFmt:v=>rs(v),
    bandas:[{de:-2600,ate:0,cor:'#FBF2F3'}],
    segmentos:[{x:eq,y1:-2600,y2:1600,cor:COR.ouro,larg:1.8,r:'equilíbrio em '+pct(eq,2)}],
    marcas:[{x:pd,y:c8uma([pd],[C8EAD]).esperado,
      cor:c8uma([pd],[C8EAD]).esperado>=0?COR.ok:COR.alerta,r:rs(c8uma([pd],[C8EAD]).esperado)}],
    w:560,h:320});};
  sl.addEventListener('input',upd);upd();},
 conexao:'Uma operação tem limiar. Uma carteira tem corte, e escolher o corte é trocar uma coisa por outra.',
 guia:undefined});

/* =========================== página 7 =========================== */
P({id:'c8p7',cap:8,n:7,nivel:'essencial',t:{exp:3,ex:2,prat:2,disc:2},origem:'rec',
 titulo:'Apertar o corte troca defaults evitados por bons recusados, e a troca se conta em reais',
 aprendizado:'Toda mudança de corte evita defaults e recusa bons ao mesmo tempo, e a decisão só é possível quando os dois lados aparecem em reais, não em número de propostas.',
 apoio:'Carteira da janela fora do tempo, '+C8N+' propostas. Mova o corte e acompanhe o que foi evitado e o que foi abandonado, com os dois lados medidos pelo mesmo motor.',
 visual:()=>`<div class="palcoflex"><div class="esq">
  <div class="ctrl"><label for="c8p7c">Corte de aprovação em PD <b id="c8p7cv"></b></label>
   <input type="range" id="c8p7c" min="20" max="460" step="5" value="100"></div>
  <div id="c8p7k"></div>
  <p class="nota" style="margin-top:9px">Contagem retrospectiva na janela fora do tempo, onde o desfecho
  já é conhecido. No momento da decisão o banco não sabe quem vai dar default: sabe apenas a PD. Esta
  tela mede o preço da política depois do fato, que é exatamente o que um comitê de revisão faz.
  Revisão manual desligada aqui, para isolar o efeito do corte. ${selo('rec')}</p>
  </div><div class="dir"><div id="c8p7o"></div></div></div>`,
 init:()=>{const sl=document.getElementById('c8p7c');
  const upd=()=>{const c=+sl.value/1000;
   document.getElementById('c8p7cv').textContent=pct(c,1);
   const r=avaliaCarteira(C8OPS,{corte:c,corteRev:c,capacidadeRevisao:0,...C8PAR});
   const rec=C8TODAS.registros.filter(x=>x.pd>c);
   const maus=rec.filter(x=>x.y===1),bons=rec.filter(x=>x.y===0);
   const evitado=-maus.reduce((s,x)=>s+x.realizado,0);
   const abandonado=bons.reduce((s,x)=>s+x.realizado,0);
   const saldo=evitado-abandonado;
   const w=wilson(maus.length,rec.length||1);
   const fecha=Math.abs(r.realizado-(C8TODAS.realizado+saldo))<1e-6;
   document.getElementById('c8p7k').innerHTML=`<div class="painel"><div class="grade g2">
    <div><div class="rot">Aprovados</div><div class="numg">${r.nAprov}</div>
     <div class="nota">de ${r.n}, ${pct(r.taxaAprov,1)} da carteira</div></div>
    <div><div class="rot">Resultado esperado</div><div class="numg">${rsk(r.esperado)}</div>
     <div class="nota">pelo motor econômico, corte em ${pct(c,1)}</div></div></div></div>`;
   document.getElementById('c8p7o').innerHTML=`<div class="painel">
    <h3>O que a recusa evitou e o que ela abandonou ${selo('rec')}</h3>
    <div class="rolax"><table style="margin-top:7px"><thead><tr><th>Grupo recusado</th>
     <th>Propostas</th><th>Exposição</th><th>Em reais</th></tr></thead><tbody>
    <tr><th scope="row">Recusados que deram default</th><td class="num">${maus.length}</td>
     <td class="num">${rsk(maus.reduce((s,x)=>s+x.ead,0))}</td>
     <td class="num" style="color:var(--ok)">${rsk(evitado)} evitados</td></tr>
    <tr><th scope="row">Recusados que teriam pago</th><td class="num">${bons.length}</td>
     <td class="num">${rsk(bons.reduce((s,x)=>s+x.ead,0))}</td>
     <td class="num" style="color:var(--alerta)">${rsk(abandonado)} abandonados</td></tr>
    <tr style="font-weight:700;background:#EFF3FA"><th scope="row">Saldo da recusa</th>
     <td class="num">${rec.length}</td><td class="num">${rsk(rec.reduce((s,x)=>s+x.ead,0))}</td>
     <td class="num" style="color:${saldo>=0?'var(--ok)':'var(--alerta)'}">${rsk(saldo)}</td></tr>
    </tbody></table></div>
    <div class="grade g2" style="margin-top:10px">
     <div class="revelacao"><b>Taxa de default entre os recusados.</b>
      ${rec.length?pct(w.p,1):'n/d'}, intervalo de Wilson de ${rec.length?pct(w.lo,1):'n/d'} a
      ${rec.length?pct(w.hi,1):'n/d'} com ${rec.length} propostas. Toda proporção usada para decidir
      vem com intervalo, como no capítulo 7.</div>
     <div class="revelacao ${fecha?'bom':'ruim'}"><b>Conferência.</b> O resultado realizado da carteira
      inteira é ${rsk(C8TODAS.realizado)}. Somando o saldo da recusa, ${rsk(saldo)}, chega-se a
      ${rsk(C8TODAS.realizado+saldo)}, que é o realizado da carteira aprovada com corte de ${pct(c,1)}
      calculado pelo motor: ${rsk(r.realizado)}. ${fecha?'Fecha.':'Não fecha.'}</div></div>
    <div class="revelacao ruim" style="margin-top:10px"><h4>Por que contar em propostas engana</h4>
    Neste corte a recusa atinge ${maus.length} futuros defaults e ${bons.length} bons pagadores. Em
    número de propostas a política parece desproporcional. Em reais o saldo é ${rsk(saldo)}, porque as
    exposições e as margens dos dois grupos não são iguais. Contagem de propostas e saldo em reais
    podem apontar para lados opostos, e é o segundo que paga a folha.</div></div>`;};
  sl.addEventListener('input',upd);upd();},
 conexao:'Se cada corte tem um saldo, a sequência de saldos desenha uma curva com um máximo.',
 guia:undefined});

