/* ======== v3/28_cap10.js ======== */
/* ==================== CAPÍTULO 10: laboratório integrado ====================
   Comitê de crédito em duas rodadas, memorando de cinco campos e rubrica.
   Regra do capítulo: todo número monetário sai de avaliaCarteira, toda tela
   que exibe totais fecha pela função ponte, e o estado do choque aparece na
   mesma tela em que aparece o número, da página 12 até o fechamento.
   ========================================================================== */
const C10PAR={lgd:0.65,taxaReceita:0.28,custoFunding:0.12,custoOper:120,
  custoCapital:0.02,custoRevisao:90};
const C10OPS={id:DADOS.oot.y.map((_,i)=>i),pd:DADOS.oot.pl,ead:DADOS.oot.ead,
  y:DADOS.oot.y,pdTrue:DADOS.oot.pt};
const C10N=C10OPS.pd.length, C10D=C10OPS.y.reduce((s,v)=>s+v,0);
const C10CMP=DADOS.res.comparacao_auc;
const C10LOG=DADOS.res.logit_oot, C10GBM=DADOS.res.gbm_platt_oot;

/* zero exibido é sempre zero, nunca zero negativo de arredondamento */
const c10z=v=>v===null||v===undefined?v:Math.abs(v)<0.5?0:v;

/* ------------------------------------------------------------------ */
/* o choque do comitê: dois deslocamentos de premissa e um de PD.      */
/* O desfecho observado é do passado e nunca é deslocado, então sob    */
/* choque nenhuma tela deste capítulo exibe resultado realizado.       */
const C10CH={k:0.30,custoFunding:0.21,lgd:0.80,
  nome:'funding de 12% para 21%, perda no default de 65% para 80% e PD deslocada em 0,30 em log odds'};

const c10base=modelo=>modelo==='gbm'?DADOS.oot.pg:DADOS.oot.pl;
const c10ops=(modelo,comChoque)=>{const b=c10base(modelo);
  return comChoque?{id:C10OPS.id,ead:C10OPS.ead,y:C10OPS.y,
      pd:b.map(p=>sigmoid(logit(p)+C10CH.k)),
      pdTrue:C10OPS.pdTrue.map(p=>sigmoid(logit(p)+C10CH.k))}
    :{id:C10OPS.id,ead:C10OPS.ead,y:C10OPS.y,pd:b,pdTrue:C10OPS.pdTrue};};

/* política congelada no capítulo 8, com queda para um valor declarado quando
   o aluno chegou aqui sem ter congelado nada */
function c10pol(){const p=pega('politica_c8',null);
  return p?{corte:p.corte,corteRev:Math.max(p.corteRev,p.corte),
      capacidade:p.capacidade,qualidade:p.qualidade,congelada:true,quando:p.quando}
    :{corte:0.12,corteRev:0.30,capacidade:80,qualidade:0.6,congelada:false,quando:null};}

const c10aval=(modelo,pol,comChoque)=>avaliaCarteira(c10ops(modelo,comChoque),
  {corte:pol.corte,corteRev:Math.max(pol.corteRev,pol.corte),
   capacidadeRevisao:pol.capacidade,qualidadeRevisao:pol.qualidade,...C10PAR,
   ...(comChoque?{custoFunding:C10CH.custoFunding,lgd:C10CH.lgd}:{})});

/* uma operação isolada avaliada pelo MESMO motor da carteira */
const c10uma=(pd,ead,extra={})=>avaliaCarteira({id:[0],pd:[pd],ead:[ead]},
  {corte:1,corteRev:1,capacidadeRevisao:0,...C10PAR,...extra});

/* ------------------------------------------------------------------ */
/* estado do choque, gravado e exibido. Nunca há choque em silêncio.   */
const c10choque=()=>pega('choque_c10',{aplicado:false,quando:null});
function c10faixa(){const ch=c10choque();
  return ch.aplicado
   ?`<div class="revelacao ruim" style="margin:0 0 11px;padding:9px 12px">
     <b>Estado do cenário: choque aplicado.</b> ${esc(C10CH.nome)}.
     Todo número desta tela está sob esse choque, inclusive os que vieram de páginas anteriores.
     O resultado realizado não é exibido sob choque, porque o desfecho observado é do passado e não
     foi deslocado. ${ch.quando?'Aplicado em '+esc(ch.quando)+'.':''}
     A página 12 tem o botão que devolve o cenário base.</div>`
   :`<div class="revelacao bom" style="margin:0 0 11px;padding:9px 12px">
     <b>Estado do cenário: base.</b> Nenhum choque aplicado. Funding em ${pct(C10PAR.custoFunding,0)},
     perda no default em ${pct(C10PAR.lgd,0)} e PD do modelo sem deslocamento.</div>`;}

/* ------------------------------------------------------------------ */
/* memorando de cinco campos, construído um campo por página           */
const C10CAMPOS=[
 {k:'recomendacao',rot:'Campo 1 de 5: recomendação',
  label:'Escreva a recomendação em até cinco linhas: modelo, corte, faixa de revisão, capacidade e por quanto tempo a decisão vale.',
  itens:['Nomeia o modelo principal e o modelo mantido em paralelo',
         'Traz corte, teto da faixa de revisão e capacidade em números',
         'Declara a finalidade da PD: ordenar, precificar ou provisionar',
         'Declara a validade da decisão e a data da próxima revisão',
         'Diz quem assina e quem executa']},
 {k:'evidencia',rot:'Campo 2 de 5: evidência',
  label:'Liste a evidência que sustenta a recomendação. Cada número com amostra, denominador e origem.',
  itens:['Toda métrica vem de amostra que não participou do ajuste',
         'Ordenação e calibração aparecem separadas, e não como um índice só',
         'Cada proporção usada para decidir vem com intervalo e denominador',
         'O resultado econômico vem da mesma carteira e fecha pela ponte',
         'A estabilidade da entrada vem com os cortes congelados no treino']},
 {k:'incerteza',rot:'Campo 3 de 5: incerteza',
  label:'Escreva o que a evidência não decide. Diga onde ela é fraca e o que ainda pode inverter a recomendação.',
  itens:['A comparação de ordenação é apresentada com intervalo, não com rótulo de vencedor',
         'O tamanho da amostra fora do tempo e o número de defaults estão escritos',
         'O viés de seleção da base de aprovados está declarado',
         'A base é sintética e isso está dito no corpo do memorando',
         'Nenhuma associação é apresentada como causa']},
 {k:'condicoes',rot:'Campo 4 de 5: condições',
  label:'Escreva as condições de aprovação: o que precisa existir antes da entrada em produção e o que suspende a decisão.',
  itens:['Condição sobre motivo de recusa individual, exigível por regulação',
         'Condição sobre validação independente, com escopo e prazo',
         'Condição sobre monotonicidade nas variáveis com direção econômica clara',
         'Condição de suspensão: o que faz a decisão voltar ao comitê antes do prazo',
         'Cada condição tem responsável nomeado e data']},
 {k:'plano',rot:'Campo 5 de 5: plano de acompanhamento',
  label:'Traga o plano do capítulo 9: indicadores, limiar, janela, responsável e ação, mais o que o painel não vê.',
  itens:['Um indicador para deslocamento de entrada',
         'Um indicador para mudança de nível',
         'Um indicador para mudança de relação, em safra madura',
         'Pelo menos um indicador que não espera rótulo',
         'O que o painel não mede, escrito como limitação e não omitido']}];

const c10memo=()=>pega('memo_c10',{});
const c10ck=()=>pega('memo_c10_ck',{});

function c10campoUI(c){const m=c10memo(),k=c10ck();
  return `<div class="painel"><div class="rot">${esc(c.rot)}</div>
   <div class="ctrl" style="margin-top:8px"><label for="memo_${c.k}">${esc(c.label)}</label>
    <textarea id="memo_${c.k}" rows="7" style="width:100%;border:1px solid var(--regua);
     border-radius:5px;padding:8px;font-family:inherit;font-size:13.5px">${esc(m[c.k]||'')}</textarea></div>
   <div class="rot" style="margin-top:11px">O que a rubrica procura neste campo</div>
   <div style="margin-top:5px">${c.itens.map((it,i)=>`<label class="opcao"
     style="padding:6px 9px;min-height:0;margin-bottom:5px;display:block">
     <input type="checkbox" data-ck="${c.k}_${i}" ${k[c.k+'_'+i]?'checked':''}> ${esc(it)}</label>`).join('')}</div>
   <div id="v_${c.k}" class="revelacao" style="margin-top:9px;padding:8px 11px"></div></div>`;}

function c10ligaCampo(c){const t=document.getElementById('memo_'+c.k);if(!t)return;
  const v=document.getElementById('v_'+c.k);
  const upd=()=>{const m=c10memo();m[c.k]=t.value;poe('memo_c10',m);
   const k=c10ck(),marcados=c.itens.filter((_,i)=>k[c.k+'_'+i]).length;
   const n=t.value.trim().length;
   const ok=marcados===c.itens.length&&n>=120;
   v.className='revelacao '+(ok?'bom':marcados===0&&n===0?'':'ruim');
   v.innerHTML=ok
    ?`<b>Campo completo.</b> ${c.itens.length} de ${c.itens.length} itens declarados e ${n} caracteres
      escritos. A rubrica ainda pode reprovar este campo se o texto afirmar mais do que a evidência sustenta.
      Marcar item não é o mesmo que cumprir item, e o revisor lê o texto, não as caixas.`
    :`<b>Campo incompleto.</b> ${marcados} de ${c.itens.length} itens declarados e ${n} caracteres
      escritos. Faltam ${c.itens.length-marcados} itens${n<120?' e o texto ainda está curto para ser avaliável':''}.`;};
  t.addEventListener('input',upd);t.addEventListener('change',upd);
  document.querySelectorAll('[data-ck]').forEach(el=>el.addEventListener('change',()=>{
    const k=c10ck();k[el.getAttribute('data-ck')]=el.checked;poe('memo_c10_ck',k);upd();}));
  upd();}

