/* ======== v3/40_app.js ======== */
/* ============================================================================
   Casca da aplicação: navegação por aula e capítulo, três experiências de uso,
   mapa do curso nas fronteiras, dois progressos distintos e QR por atividade.
   ========================================================================== */
async function baixaArquivo(nome,txt){
  try{const d=await (window.claude&&window.claude.use?window.claude.use('downloads'):null);
    if(d){await d.save({filename:nome,data:txt});return;}}
  catch(e){if(e&&(e.code==='declined'||e.code==='rate_limited'))return;}
  const dv=document.createElement('div');
  dv.setAttribute('role','dialog');dv.setAttribute('aria-label','Exportar '+nome);
  dv.style.cssText='position:fixed;inset:0;background:rgba(0,32,91,.45);z-index:98;display:flex;'
   +'align-items:center;justify-content:center;padding:18px';
  dv.innerHTML=`<div class="painel" style="max-width:620px;width:100%;max-height:86vh;overflow:auto">
   <h3>Exportar ${esc(nome)}</h3>
   <p class="nota">O download direto não está disponível nesta visualização. Copie o texto abaixo.</p>
   <textarea readonly style="width:100%;height:280px;margin-top:9px;font-family:var(--mono);font-size:12px;
    border:1px solid var(--regua);border-radius:5px;padding:9px"></textarea>
   <div class="linhabotoes" style="margin-top:10px"><button class="botao" data-cp>Copiar tudo</button>
    <button class="botao sec" data-fc>Fechar</button><span class="nota" data-fb></span></div></div>`;
  dv.querySelector('textarea').value=txt;
  dv.querySelector('[data-fc]').addEventListener('click',()=>dv.remove());
  dv.addEventListener('click',e=>{if(e.target===dv)dv.remove();});
  dv.querySelector('[data-cp]').addEventListener('click',async()=>{
   const ta=dv.querySelector('textarea');ta.select();let ok=false;
   try{await navigator.clipboard.writeText(txt);ok=true;}catch(e){try{ok=document.execCommand('copy');}catch(e2){}}
   dv.querySelector('[data-fb]').textContent=ok?'Copiado.':'Use Ctrl+C.';});
  document.body.appendChild(dv);dv.querySelector('[data-cp]').focus();
}

/* ======== capítulo 11: construção de modelos com IA ======== */
function promptIA(etapa,arquivos,tarefa,entrega,verificacoes){
 return `Você está atuando como analista de risco de crédito em um projeto educacional de probabilidade de default.

CONTEXTO E OBJETIVO
O objetivo é construir um modelo de PD para estimar a probabilidade de default em 12 meses após a concessão. A unidade de observação é uma proposta de crédito. Use somente informações disponíveis na data da decisão. O trabalho deve ser reproduzível e será defendido por quem o executou.

ETAPA ATUAL
${etapa}

ARQUIVOS DISPONÍVEIS
${arquivos}

DEFINIÇÕES JÁ APROVADAS
População: propostas da população documentada no arquivo problema-negocio.md.
Evento: default conforme definicao-default.md.
Horizonte: 12 meses após a concessão.
Divisão temporal: treino, validação e teste fora do tempo, sem usar o teste para escolher o modelo.

RESTRIÇÕES
Não use o conjunto de teste para escolher variáveis, imputações, hiperparâmetros, calibradores ou limiares. Identifique variáveis potencialmente indisponíveis na data da decisão antes de treinar. Faça o pré-processamento aprender parâmetros apenas no treino. Preserve identificadores nas previsões. Use semente declarada.

TAREFA
${tarefa}

FORMATO DA ENTREGA
${entrega}

VERIFICAÇÕES OBRIGATÓRIAS
${verificacoes}

CONDIÇÕES PARA INTERROMPER
Interrompa e descreva a inconsistência se faltar um arquivo, se duas definições conflitarem, se a data necessária não existir, se a amostra não permitir a divisão proposta ou se você não conseguir executar o código. Não invente resultados nem afirme que executou código se não houve execução. Diferencie proposta, código produzido e resultado observado. Gere verificações capazes de detectar erros, em vez de apenas confirmar que o código terminou.`;
}
function tempoIA(m){return m===5?{exp:2,ex:1,prat:1,disc:1}:{exp:m-5,ex:2,prat:2,disc:1};}
