function ligaIA(e){
 document.querySelectorAll('input[name="ia_leak"]').forEach(inp=>inp.addEventListener('change',()=>{
  const r=document.querySelector('[data-resp-ia]');if(!r)return;r.classList.remove('oculto');
  const ok=inp.value==='nao';r.className='revelacao '+(ok?'bom':'ruim');
  r.innerHTML=ok?'<b>Correto.</b> O campo só existe depois da decisão e contém informação do próprio alvo.':'<b>Vazamento.</b> Poder preditivo perfeito pode ser apenas o futuro entrando no modelo.';}));
 const b=document.querySelector('[data-copiar]');if(!b)return;
 b.addEventListener('click',async()=>{const txt=e.prompt;let ok=false;
  try{await navigator.clipboard.writeText(txt);ok=true;}catch(err){
   const ta=document.createElement('textarea');ta.value=txt;document.body.appendChild(ta);ta.select();
   try{ok=document.execCommand('copy');}catch(e2){}ta.remove();}
  const st=document.querySelector('[data-copiado]');if(st)st.textContent=ok?'Prompt copiado.':'Selecione o texto para copiar.';});
}
