/* Todas as equações são mantidas como fonte LaTeX e renderizadas pelo MathJax. */
function latexDaFormula(texto){
 const t=texto.replace(/\s+/g,' ').trim(),num=x=>x.replace(/,/g,'{,}');
 if(t.startsWith('características observadas'))return String.raw`\text{características observadas}\;\longrightarrow\;\text{regra}\;\longrightarrow\;\text{estimativa}`;
 if(t.startsWith('p̂ =')){const m=t.match(/p̂ = ([\d,]+) ÷ ([\d,]+) = ([\d,]+)/);if(m)return String.raw`\widehat p=\frac{${m[1]}}{${m[2]}}=${num(m[3])}`;}
 if(t.startsWith('P(default'))return String.raw`P(Y=1\mid\text{condição})=\frac{\text{defaults no grupo}}{\text{propostas no grupo}}`;
 if(t.startsWith('1. escolher'))return String.raw`1.\ \text{escolher a família}\;\longrightarrow\;2.\ \text{escrever o critério}\;\longrightarrow\;3.\ \text{otimizar o critério}`;
 if(t.startsWith('perda ='))return String.raw`\mathcal L(p)=-\frac{1\ln(p)+7\ln(1-p)}{8}`;
 if(t.startsWith('p = 1 ÷'))return String.raw`p=\frac{1}{1+e^{-b}},\qquad g=p-0{,}125,\qquad b\leftarrow b-2g`;
 if(t.startsWith('largura ≈'))return String.raw`\text{largura do intervalo}\ \propto\ \frac{1}{\sqrt n}`;
 if(t.startsWith('campo elegível'))return String.raw`\text{data do evento}+\text{latência da fonte}\leq\text{data da decisão}`;
 if(t.startsWith('odds corrigida'))return String.raw`\operatorname{odds}_{\rm corrigida}=\operatorname{odds}_{\rm amostra}\,\frac{\pi/(1-\pi)}{\pi_a/(1-\pi_a)}`;
 if(t.startsWith('IV ='))return String.raw`IV=\sum_j\left(p_{j,\rm bons}-p_{j,\rm maus}\right)\operatorname{WoE}_j`;
 if(t.startsWith('odds ='))return String.raw`\operatorname{odds}=\frac{PD}{1-PD},\qquad PD=\frac{\operatorname{odds}}{1+\operatorname{odds}}`;
 if(t.startsWith('log odds'))return String.raw`\operatorname{logit}(PD)=\ln\!\left(\frac{PD}{1-PD}\right)`;
 if(t.startsWith('PD = 1 ÷'))return String.raw`PD=\frac{1}{1+e^{-z}},\qquad z=\ln\!\left(\frac{PD}{1-PD}\right)`;
 if(t.startsWith('z = β₀'))return String.raw`z=\beta_0+\beta_1\frac{u}{10}+\beta_2\frac{a}{10}`;
 if(/^z = [-\d]/.test(t))return t.replace(/−/g,'-').replace(/×/g,String.raw`\cdot `).replace(/,/g,'{,}');
 if(t.startsWith('razão de chances'))return String.raw`\operatorname{OR}=e^{\beta},\qquad \beta=\ln(\operatorname{OR})`;
 if(t.startsWith('perda(β₀'))return String.raw`\begin{aligned}\mathcal L(\boldsymbol\beta)&=-\frac1n\sum_{i=1}^n\left[y_i\ln p_i+(1-y_i)\ln(1-p_i)\right]\\[3pt]p_i&=\sigma\!\left(\beta_0+\beta_1\frac{u_i}{10}+\beta_2\frac{a_i}{10}\right)\end{aligned}`;
 if(t.startsWith('g₀ ='))return String.raw`g_0=\overline{(p-y)},\quad g_1=\overline{(p-y)u/10},\quad g_2=\overline{(p-y)a/10},\quad \boldsymbol\beta\leftarrow\boldsymbol\beta-0{,}10\,\mathbf g`;
 if(t.startsWith('fronteira:'))return String.raw`\beta_0+\beta_1\frac{u}{10}+\beta_2\frac{a}{10}=\ln\!\left(\frac{c}{1-c}\right)`;
 if(t.startsWith('Gini ='))return String.raw`G=2p(1-p),\qquad H=-p\log_2p-(1-p)\log_2(1-p)`;
 if(t.startsWith('ganho = Gini'))return String.raw`\Delta G=G_{\rm antes}-\left(\frac{n_L}{n}G_L+\frac{n_R}{n}G_R\right)`;
 if(t.startsWith('custo(T)'))return String.raw`R_\alpha(T)=R(T)+\alpha\,|\operatorname{folhas}(T)|`;
 if(t.startsWith('previsão final'))return String.raw`\widehat y_M=\widehat y_0+h_1+h_2+\cdots+h_M`;
 if(t.startsWith('F₀ = média')){const m=t.match(/= ([\d,]+).*?= ([\d,]+)/);return String.raw`F_0=\bar y=${m?num(m[1]):''},\qquad MSE_0=${m?num(m[2]):''}`;}
 if(t.startsWith('F_m(x)'))return String.raw`F_m(x)=F_{m-1}(x)+\eta\,h_m(x)`;
 if(t.startsWith('F_M(x) = F₀(x)'))return String.raw`F_M(x)=F_0(x)+\eta\sum_{m=1}^{M}h_m(x)`;
 if(t.startsWith('F_M(x) = F₀ +'))return String.raw`F_M(x)=F_0+\eta\sum_{m=1}^{M}h_m(x),\quad F_0=\ln\!\left(\frac{\pi}{1-\pi}\right),\quad PD(x)=\sigma(F_M(x))`;
 if(t.startsWith('perda de um ponto'))return String.raw`\ell(y,p)=-\left[y\ln p+(1-y)\ln(1-p)\right],\qquad p=\sigma(F)`;
 if(t.startsWith('acerto ='))return String.raw`\operatorname{acurácia}=\frac{\text{defaults recusados}+\text{adimplentes aprovados}}{n}`;
 if(t.startsWith('AUC =')){const m=t.match(/AUC = \(([^)]+)\) ÷ ([\d,]+) = ([\d,]+)/);return m?String.raw`AUC=\frac{${m[1].replace(/\+/g,'+')}}{${m[2]}}=${num(m[3])}`:String.raw`AUC=P(s_{\rm mau}>s_{\rm bom})+\tfrac12P(s_{\rm mau}=s_{\rm bom})`;}
 if(t.startsWith('ganho(x)'))return String.raw`\operatorname{ganho}(x)=\frac{D_{\rm piores\ }x\%}{D_{\rm total}},\qquad \operatorname{alavancagem}(x)=\frac{\operatorname{ganho}(x)}{x}`;
 if(t.startsWith('compatibilidade na faixa'))return String.raw`\overline{PD}_j\in IC_{95\%}^{\rm Wilson}(\widehat p_j)`;
 if(t.startsWith('Brier ='))return String.raw`\operatorname{Brier}=\frac1n\sum_{i=1}^{n}(p_i-y_i)^2,\qquad \operatorname{LogLoss}=-\frac1n\sum_{i=1}^{n}\left[y_i\ln p_i+(1-y_i)\ln(1-p_i)\right]`;
 if(t.startsWith('p calibrada')){const m=t.match(/sigmoide\( ([^ ]+) \+ ([^ ]+)/);return String.raw`p_{\rm cal}=\sigma\!\left(${m?num(m[1]):'a'}+${m?num(m[2]):'b'}\,\operatorname{logit}(p_{\rm bruta})\right)`;}
 if(t.startsWith('perda no default'))return String.raw`L_D=LGD\cdot EAD,\qquad EL=PD\cdot LGD\cdot EAD`;
 if(t.startsWith('EL ='))return String.raw`EL=PD\cdot LGD\cdot EAD=12\%\cdot65\%\cdot EAD`;
 if(t.startsWith('Resultado ='))return String.raw`\Pi=(1-PD)R-PD\cdot LGD\cdot EAD-F-O-K=R\$\,350`;
 if(t.startsWith('(1 − PD)'))return String.raw`\begin{aligned}(1-PD)R-PD\cdot LGD\cdot EAD-F-O-K&=0\\ PD^*&=\frac{R-F-O-K}{R+LGD\cdot EAD}\end{aligned}`;
 if(t.startsWith('PD* =')){const m=t.match(/= ([\d,]+)%$/);return String.raw`PD^*=\frac{R\$\,2.800-R\$\,1.200-R\$\,120-R\$\,200}{R\$\,2.800+R\$\,6.500}=${m?num(m[1]):'13{,}76'}\%`;}
 if(t.startsWith('receita esperada'))return String.raw`\text{receita esperada}=\text{valor exibido no cenário}`;
 if(t.startsWith('contribuição da faixa'))return String.raw`\psi_j=(q_j-p_j)\ln\!\left(\frac{q_j}{p_j}\right),\qquad PSI=\sum_{j=1}^{10}\psi_j`;
 return String.raw`\text{${t.replace(/[{}\\]/g,'')}}`;
}
