function progressoApresentacao(){
  const total=LISTA.length;return {feito:Math.min(AT+1,total),total};
}
function progressoAtividades(){
  const ids=[];PAGINAS.forEach(p=>{
    const src=(p.visual?String(p.visual):'')+(p.init?String(p.init):'');
    const m=src.match(/questao\('([a-z0-9_]+)'/g)||[];
    m.forEach(x=>ids.push(x.replace(/questao\('|'/g,'')));
    const m2=src.match(/prever\('([a-z0-9_]+)'/g)||[];
    m2.forEach(x=>ids.push(x.replace(/prever\('|'/g,'')));});
  const unicos=[...new Set(ids)];
  let resolvidas=0;
  unicos.forEach(id=>{const q=pega('q_'+id,null);
    if(q&&q.resolvido)resolvidas++;else if(pega('p_'+id,-1)>=0)resolvidas++;});
  return {feito:resolvidas,total:unicos.length};
}

/* ---------------- exploração geral de gráficos e tabelas ----------------
   As interações específicas de cada página continuam sendo a principal forma de
   aprendizagem. Esta camada acrescenta ampliação, comparação e inspeção sem
   alterar a ordem original do material ou os dados exibidos.                   */
function fechaExplorador(fundo,origem){
  if(!fundo)return;
  fundo.remove();
  if(origem&&document.contains(origem))origem.focus();
}
function criaExplorador(titulo,origem){
  const fundo=document.createElement('div');
  fundo.className='explorador-fundo';
  fundo.setAttribute('role','presentation');
  fundo.innerHTML=`<section class="explorador" role="dialog" aria-modal="true" aria-label="${esc(titulo)}">
   <header class="explorador-topo"><h3>${esc(titulo)}</h3>
    <div class="explorador-controles" data-controles></div>
    <button type="button" class="botao sec min" data-fechar>Fechar</button></header>
   <div class="explorador-corpo"></div><div class="explorador-status" aria-live="polite"></div></section>`;
  const fecha=()=>fechaExplorador(fundo,origem);
  fundo.querySelector('[data-fechar]').addEventListener('click',fecha);
  fundo.addEventListener('click',e=>{if(e.target===fundo)fecha();});
  fundo.addEventListener('keydown',e=>{
    if(e.key==='Escape'){e.preventDefault();fecha();return;}
    if(e.key!=='Tab')return;
    const foc=[...fundo.querySelectorAll('button,input,[href],select,textarea')]
      .filter(x=>!x.disabled&&x.offsetParent!==null);
    if(!foc.length)return;
    const p=foc.indexOf(document.activeElement);
    if(e.shiftKey&&p<=0){e.preventDefault();foc[foc.length-1].focus();}
    else if(!e.shiftKey&&p===foc.length-1){e.preventDefault();foc[0].focus();}
  });
  document.body.appendChild(fundo);
  return fundo;
}
function normalizaBusca(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function valorOrdenacao(s){
  const t=String(s||'').trim();
  const data=t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
  if(data)return {tipo:'n',v:+new Date(+data[3],+data[2]-1,+data[1])};
  const limpo=t.replace(/\s/g,'').replace(/^R\$/i,'').replace(/%$/,'');
  if(/^[-+]?\d[\d.,]*$/.test(limpo)){
    const n=limpo.includes(',')?Number(limpo.replace(/\./g,'').replace(',','.')):Number(limpo);
    if(Number.isFinite(n))return {tipo:'n',v:n};
  }
  return {tipo:'s',v:normalizaBusca(t)};
}
function abreTabela(origem,table){
  const fundo=criaExplorador('Explorar tabela',origem);
  const controles=fundo.querySelector('[data-controles]');
  controles.innerHTML=`<label>Filtrar linhas<input type="search" placeholder="Digite um termo" data-filtro></label>
   <button type="button" class="botao sec min" data-restaurar>Restaurar ordem</button>`;
  const corpo=fundo.querySelector('.explorador-corpo');
  corpo.classList.add('explorador-tabela');
  const clone=table.cloneNode(true),tbody=clone.tBodies[0];
  clone.removeAttribute('style');
  const originais=tbody?[...tbody.rows].map((r,i)=>({r:r.cloneNode(true),i})):[];
  let coluna=-1,direcao=1;
  const status=fundo.querySelector('.explorador-status');
  const linhas=()=>tbody?[...tbody.rows]:[];
  const informa=()=>{const vis=linhas().filter(r=>!r.hidden).length;
    status.textContent=`${vis} linha${vis===1?'':'s'} visível${vis===1?'':'eis'}. Clique em uma linha para destacá-la.`;};
  if(clone.tHead){[...clone.tHead.rows[clone.tHead.rows.length-1].cells].forEach((th,i)=>{
    const rot=th.textContent.trim()||`Coluna ${i+1}`;
    th.innerHTML=`<button type="button" aria-label="Ordenar por ${esc(rot)}"><span>${th.innerHTML}</span><span aria-hidden="true" data-seta>↕</span></button>`;
    th.querySelector('button').addEventListener('click',()=>{
      direcao=coluna===i?-direcao:1;coluna=i;
      const arr=linhas().map((r,j)=>({r,j,v:valorOrdenacao(r.cells[i]?r.cells[i].textContent:'')}));
      arr.sort((a,b)=>{let c;if(a.v.tipo==='n'&&b.v.tipo==='n')c=a.v.v-b.v.v;
        else c=String(a.v.v).localeCompare(String(b.v.v),'pt-BR',{numeric:true,sensitivity:'base'});
        return (c||a.j-b.j)*direcao;});
      arr.forEach(x=>tbody.appendChild(x.r));
      clone.querySelectorAll('[data-seta]').forEach(x=>x.textContent='↕');
      th.querySelector('[data-seta]').textContent=direcao>0?'↑':'↓';
      status.textContent=`Tabela ordenada por ${rot}, em ordem ${direcao>0?'crescente':'decrescente'}.`;
    });
  });}
  clone.addEventListener('click',e=>{const r=e.target.closest('tbody tr');if(!r)return;
    const ligado=r.dataset.selecionada!=='true';linhas().forEach(x=>delete x.dataset.selecionada);
    if(ligado)r.dataset.selecionada='true';informa();});
  corpo.appendChild(clone);
  const filtro=controles.querySelector('[data-filtro]');
  filtro.addEventListener('input',()=>{const q=normalizaBusca(filtro.value);
    linhas().forEach(r=>r.hidden=q&&!normalizaBusca(r.textContent).includes(q));informa();});
  controles.querySelector('[data-restaurar]').addEventListener('click',()=>{
    if(!tbody)return;tbody.innerHTML='';originais.forEach(x=>tbody.appendChild(x.r.cloneNode(true)));
    coluna=-1;direcao=1;filtro.value='';informa();});
  informa();filtro.focus();
}
function abreGrafico(origem,svgOriginal){
  const fundo=criaExplorador('Explorar gráfico',origem);
  const controles=fundo.querySelector('[data-controles]');
  controles.innerHTML=`<button type="button" class="botao sec min" data-menos aria-label="Reduzir gráfico">−</button>
   <button type="button" class="botao sec min" data-mais aria-label="Ampliar gráfico">+</button>
   <button type="button" class="botao sec min" data-reset>Restaurar</button>`;
  const corpo=fundo.querySelector('.explorador-corpo');
  corpo.classList.add('explorador-grafico');
  const suporte=document.createElement('div'),clone=svgOriginal.cloneNode(true);
  clone.removeAttribute('style');clone.setAttribute('role','img');
  suporte.appendChild(clone);corpo.appendChild(suporte);
  const vb=(clone.getAttribute('viewBox')||'0 0 800 500').split(/\s+/).map(Number);
  const razao=(vb[2]>0&&vb[3]>0)?vb[3]/vb[2]:.625;
  let zoom=1;
  const status=fundo.querySelector('.explorador-status');
  const aplica=()=>{const base=Math.max(520,Math.min(1080,corpo.clientWidth-30));
    suporte.style.width=(base*zoom)+'px';suporte.style.height=(base*razao*zoom)+'px';
    status.textContent=`Ampliação ${Math.round(zoom*100)}%. Use a rolagem para deslocar e clique em uma marca para destacá-la.`;};
  const muda=d=>{zoom=Math.max(.6,Math.min(3,Math.round((zoom+d)*10)/10));aplica();};
  controles.querySelector('[data-mais]').addEventListener('click',()=>muda(.2));
  controles.querySelector('[data-menos]').addEventListener('click',()=>muda(-.2));
  controles.querySelector('[data-reset]').addEventListener('click',()=>{zoom=1;corpo.scrollTo(0,0);
    clone.querySelectorAll('[data-destaque]').forEach(x=>x.removeAttribute('data-destaque'));aplica();});
  corpo.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();muda(e.deltaY<0?.1:-.1);},{passive:false});
  clone.addEventListener('click',e=>{const marca=e.target.closest('circle,rect,path,polyline,polygon,line');
    if(!marca)return;clone.querySelectorAll('[data-destaque]').forEach(x=>x.removeAttribute('data-destaque'));
    marca.setAttribute('data-destaque','true');status.textContent='Marca destacada. Use Restaurar para limpar o destaque.';});
  requestAnimationFrame(aplica);controles.querySelector('[data-mais]').focus();
}
function ativaExploracaoDados(){
  /* Toda tabela recebe um contêiner que preserva as colunas e oferece a
     visualização ampliada. Assim nenhuma tabela depende de caber por compressão. */
  document.querySelectorAll('#corpo table').forEach(t=>{
    if(t.closest('.rolax,.explorador'))return;
    const w=document.createElement('div');w.className='rolax';t.before(w);w.appendChild(t);
  });
  document.querySelectorAll('#corpo .rolax').forEach(w=>{
    if(w.dataset.exploravel||w.closest('.explorador'))return;
    const t=w.querySelector(':scope > table, table');
    if(!t||!t.tHead||!t.tBodies[0]||t.tBodies[0].rows.length<3)return;
    w.dataset.exploravel='tabela';
    const b=document.createElement('button');b.type='button';b.className='explorar-dados';
    b.textContent='Abrir tabela';b.setAttribute('aria-label','Abrir tabela para filtrar e ordenar');
    b.addEventListener('click',()=>abreTabela(b,t));w.insertBefore(b,w.firstChild);
  });
  document.querySelectorAll('#corpo .svgfit').forEach(w=>{
    if(w.dataset.exploravel||w.closest('.explorador'))return;
    const s=w.querySelector(':scope > svg, svg');if(!s)return;
    const marcas=s.querySelectorAll('circle,rect,path,polyline,polygon,line').length;
    if(marcas<3)return;
    w.dataset.exploravel='grafico';
    const b=document.createElement('button');b.type='button';b.className='explorar-dados';
    b.textContent='Explorar gráfico';b.setAttribute('aria-label','Abrir gráfico para ampliar e destacar marcas');
    b.addEventListener('click',()=>abreGrafico(b,s));w.insertBefore(b,w.firstChild);
  });
}

function resumeTabelasDensas(){
  document.querySelectorAll('#corpo table').forEach(t=>{
    const tb=t.tBodies&&t.tBodies[0],w=t.closest('.rolax');
    if(!tb||!w||tb.rows.length<8||t.querySelector('input,button,select,textarea')||t.closest('.explorador')||w.classList.contains('resumo-tabela'))return;
    w.classList.add('tabela-resumida');
    const linhas=[...tb.rows],mantem=new Set([0,1,2,3,linhas.length-1]);
    linhas.forEach((r,i)=>{if(!mantem.has(i)&&!r.getAttribute('style'))r.dataset.resumoOculto='true';});
    const ocultas=linhas.filter(r=>r.dataset.resumoOculto==='true').length;if(!ocultas)return;
    const b=document.createElement('button');b.type='button';b.className='tabela-toggle';
    const pinta=()=>{const aberta=w.dataset.aberta==='true';b.textContent=aberta?'Mostrar resumo':`Ver mais ${ocultas} linha${ocultas===1?'':'s'}`;b.setAttribute('aria-expanded',aberta?'true':'false');};
    b.addEventListener('click',()=>{w.dataset.aberta=w.dataset.aberta==='true'?'false':'true';pinta();});
    w.after(b);pinta();
  });
}
function adicionaChecagemRapida(p){
  const corpo=document.getElementById('corpo'),g=p&&p.guia;if(!corpo||!g||!g.pergunta||!g.resposta)return;
  if(corpo.querySelector('button,input,select,textarea,details'))return;
  const d=document.createElement('details');d.className='checagem-rapida';
  d.innerHTML=`<summary>${esc(g.pergunta)}</summary><p>${esc(g.resposta)}</p>`;corpo.appendChild(d);
}

const TEMAS_CAP={
  1:['#B36A18','#FBF1E3'],2:['#2E6B4F','#EEF6F2'],3:['#6B4E8C','#F5F0F8'],
  4:['#9A4E36','#FAF0EC'],5:['#28725B','#EDF7F3'],6:['#7B3E73','#F8EFF6'],
  7:['#B16A12','#FBF2E5'],8:['#176C73','#EAF6F6'],9:['#5C4B8A','#F2EFF8'],
  10:['#8C4A1F','#FAF0E9'],11:['#2E6B4F','#EEF6F2']};
function indiceAberto(){return pega('indice_aberto',false)===true;}
function aplicaClasseModo(m=MODO){
  document.body.className='m-'+(m==='professor'?'estudo':m)+(indiceAberto()?'':' nav-fechada');
}
function toggleIndice(){
  const aberto=!indiceAberto();poe('indice_aberto',aberto);document.body.classList.toggle('nav-fechada',!aberto);
  const b=document.getElementById('bi');if(b)b.setAttribute('aria-pressed',aberto?'true':'false');
}

/* ---------------- casca ---------------- */
function casca(){
  document.body.innerHTML=`
  <header class="topo">
   <div class="marca">Laboratório de Decisão de Crédito <i>·</i> <span id="tb"></span></div>
   <div class="cresce"></div>
   <div role="group" aria-label="Experiência de uso" style="display:flex;gap:4px">
    <button class="pill" data-modo="professor">Professor</button>
   <button class="pill" data-modo="aluno">Aluno</button>
   <button class="pill" data-modo="apresentacao">Projeção</button></div>
   <div role="group" aria-label="Duração do encontro" style="display:flex;gap:4px">
   <button class="pill" data-dur="180">180 min</button>
    <button class="pill" data-dur="120">120 min</button></div>
   <button class="pill" id="bi">Índice</button>
   <details class="menu-topo" id="menuMais"><summary class="pill">Mais</summary><div class="menu-topo-pop">
    <button class="pill so-prof" id="bg">Guia do professor</button>
    <button class="pill so-prof" id="bc">Cronômetro</button>
    <button class="pill" id="bq">QR desta página</button>
    <button class="pill" id="bm">Visão geral do curso</button>
   </div></details>
  </header>
  <div class="trilho" title="Progresso da apresentação"><i id="pg"></i></div>
  <div class="trilho" title="Progresso das atividades do aluno" style="background:#E6EDE8">
   <i id="pa" style="background:var(--ok)"></i></div>
  <div class="layout"><nav class="mapa" id="mapa" aria-label="Índice do curso"></nav>
   <main class="palco" id="palco" tabindex="-1"></main></div>
  <aside class="notas" id="notas" aria-label="Guia do professor"></aside>`;
  document.querySelectorAll('[data-modo]').forEach(b=>
    b.addEventListener('click',()=>setModo(b.dataset.modo)));
  document.querySelectorAll('[data-dur]').forEach(b=>
    b.addEventListener('click',()=>setDuracao(+b.dataset.dur)));
  document.getElementById('bg').addEventListener('click',toggleGuia);
  document.getElementById('bc').addEventListener('click',cron);
  document.getElementById('bq').addEventListener('click',painelQR);
  document.getElementById('bm').addEventListener('click',painelMapa);
  document.getElementById('bi').addEventListener('click',toggleIndice);
  document.querySelectorAll('#menuMais button').forEach(b=>b.addEventListener('click',()=>document.getElementById('menuMais').open=false));
  sincroniza();
}
function sincroniza(){
  document.querySelectorAll('[data-modo]').forEach(b=>
    b.setAttribute('aria-pressed',b.dataset.modo===MODO));
  document.querySelectorAll('[data-dur]').forEach(b=>
    b.setAttribute('aria-pressed',+b.dataset.dur===DURACAO));
  const bi=document.getElementById('bi');if(bi)bi.setAttribute('aria-pressed',indiceAberto()?'true':'false');
}
function setDuracao(d){
  const id=LISTA.length?LISTA[AT].id:null;DURACAO=d===120?120:180;poe('duracao',DURACAO);
  recalculaLista();if(id){const j=LISTA.findIndex(p=>p.id===id);AT=j>=0?j:Math.max(0,AT-1);}
  sincroniza();mapa();desenha();
}
function setModo(m){
  const id=LISTA.length?LISTA[AT].id:null;
  MODO=m;poe('modo',m);aplicaClasseModo(m);
  recalculaLista();
  if(id){const j=LISTA.findIndex(p=>p.id===id);if(j>=0)AT=j;}
  sincroniza();mapa();desenha();
}
function mapa(){
  let h='',aulaAt=null,capAt=null;
  LISTA.forEach((p,i)=>{
   const a=aulaDaPagina(p);
   if(a&&a!==aulaAt){aulaAt=a;capAt=null;
    h+=`<h4>${rotuloModulo(a)} · ${esc(a.titulo)} · ${minutosAulaAtual(a)} min de conteúdo</h4>`;}
   if(p.cap!==capAt){capAt=p.cap;const c=cap(p.cap);
    h+=`<h4 style="padding-left:14px;color:var(--ink);text-transform:none;letter-spacing:0;
     font-size:11.5px">${c.n}. ${esc(c.nome)}</h4>`;}
   const t=p.titulo.length>44?p.titulo.slice(0,42)+'…':p.titulo;
   h+=`<a href="#/${p.id}" data-i="${i}"><span class="nn">${p.n}</span>
    <span>${esc(t)}</span></a>`;});
  const pa=progressoAtividades();
  h+=`<h4>Percurso</h4><div class="nota" style="padding:0 7px 10px">
   ${LISTA.length} páginas na visualização atual. Percurso ${DURACAO} min:
   ${AULAS.reduce((s,a)=>s+minutosAulaAtual(a),0)} minutos de conteúdo, mais intervalo,
   em quatro aulas e um trabalho final.<br><br>
   Atividades resolvidas: <b>${pa.feito} de ${pa.total}</b>.</div>`;
  document.getElementById('mapa').innerHTML=h;
}
function desenha(){
  if(AT>=LISTA.length)AT=LISTA.length-1;if(AT<0)AT=0;
  const p=LISTA[AT],c=cap(p.cap),a=aulaDaPagina(p);
  const tema=TEMAS_CAP[p.cap]||TEMAS_CAP[1];
  document.documentElement.style.setProperty('--cap',tema[0]);document.documentElement.style.setProperty('--cap-soft',tema[1]);
  document.getElementById('tb').textContent=`${rotuloModulo(a)} · Capítulo ${c.n}`;
  const pr=progressoApresentacao(),pa=progressoAtividades();
  document.getElementById('pg').style.width=(pr.feito/pr.total*100).toFixed(1)+'%';
  document.getElementById('pa').style.width=(pa.total?pa.feito/pa.total*100:0).toFixed(1)+'%';
  document.querySelectorAll('#mapa a').forEach(el=>el.setAttribute('aria-current',+el.dataset.i===AT));
  const doCap=LISTA.filter(x=>x.cap===p.cap),ip=doCap.indexOf(p);
  document.body.dataset.cap=p.cap;document.body.classList.toggle('cap-abertura',ip===0);document.body.classList.toggle('cap-fechamento',ip===doCap.length-1);
  document.getElementById('palco').innerHTML=`<article class="cena">
   <div class="eyebrow"><span>${esc(c.nome)}</span>
    <b>página ${ip+1} de ${doCap.length}</b><span>${p.min} min</span>
    ${p.nivel==='complementar'?'<span class="pill" style="font-size:10px">complementar</span>':''}
    <span class="passos" aria-hidden="true">${doCap.map((_,k)=>
     `<i class="${k===ip?'on':k<ip?'fez':''}"></i>`).join('')}</span>
    <span class="cresce"></span>${p.origem?selo(p.origem):''}</div>
   <h2>${esc(p.titulo)}</h2>
   ${p.aprendizado?`<p class="aprendizagem so-estudo"><span>Objetivo</span>${esc(p.aprendizado)}</p>`:''}
   ${p.apoio?`<p class="apoio">${esc(p.apoio)}</p>`:''}
   <div id="corpo">${p.visual?p.visual():''}</div>
   ${p.conexao&&AT<LISTA.length-1?`<div class="conexao">${esc(p.conexao)}</div>`:''}
   <div class="navrod"><button class="botao sec" id="ant">← Anterior</button>
    <span class="nota">${AT+1} de ${LISTA.length}</span>
    ${AT<LISTA.length-1?'<button class="botao" id="prox">Próxima →</button>':'<span class="botao" aria-hidden="true" style="visibility:hidden">Próxima →</span>'}</div></article>`;
  document.getElementById('ant').addEventListener('click',()=>vai(AT-1));
  const proximo=document.getElementById('prox');if(proximo)proximo.addEventListener('click',()=>vai(AT+1));
  if(p.init)try{p.init()}catch(e){console.error('init',p.id,e)}
  ativaExploracaoDados();
  resumeTabelasDensas();
  adicionaChecagemRapida(p);
  aprimoraFormulas();
  guia(p);
  ajustaColunas();
  ajustaProjecao();
  if(location.hash.replace(/^#\//,'').split('?')[0]!==p.id)
    history.replaceState(null,'','#/'+p.id+(MODO==='aluno'?'?m=aluno':''));
  scrollTo({top:0,behavior:'instant'});
}
function vai(i){
  const alvo=Math.max(0,Math.min(i,LISTA.length-1));
  const de=LISTA[AT],para=LISTA[alvo];
  AT=alvo;
  if(de&&para&&de.cap!==para.cap&&MODO!=='apresentacao')marcaFronteira(de,para);
  location.hash='#/'+LISTA[AT].id+(MODO==='aluno'?'?m=aluno':'');
  desenha();
}
/* ---------------- projeção: encolhe até caber, com piso declarado ----------------
   O piso existe para que a legibilidade a 1920x1080 não seja sacrificada.
   Abaixo dele a tela rola, e a página entra no relatório de validação como
   candidata a divisão em duas.                                                  */
/* Quando o diagrama da coluna estreita é largo por natureza, as colunas trocam de
   proporção. Vale em qualquer experiência de uso, não só na projeção.            */
function ajustaColunas(){
  document.querySelectorAll('#corpo .palcoflex').forEach(pf=>{
    const e=[...pf.children].find(x=>x.classList.contains('esq'));
    const d=[...pf.children].find(x=>x.classList.contains('dir'));
    if(!e||!d)return;
    e.style.flex='';d.style.flex='';delete pf.dataset.colunas;
    const s=e.querySelector('svg');
    if(s){const vb=(s.getAttribute('viewBox')||'').split(' ');
      if(+vb[2]>=520){e.style.flex='1 1 58%';d.style.flex='1 1 42%';pf.dataset.colunas='grafico';return;}}
    const tabelas=[...e.querySelectorAll('table')];
    const colunas=tabelas.reduce((mx,t)=>Math.max(mx,t.tHead&&t.tHead.rows[0]?t.tHead.rows[0].cells.length:0),0);
    const formula=e.querySelector('.formula');
    if(!formula&&colunas<3)return;
    /* A largura acompanha a evidência. Tabelas e fórmulas deixam de disputar
       apenas 300 px com o texto explicativo. */
    const fr=(formula||colunas>=6)?.56:colunas>=5?.54:colunas>=4?.52:.48;
    e.style.flex=`${fr} 1 0px`;d.style.flex=`${1-fr} 1 0px`;pf.dataset.colunas='dados';});
}
/* Projeção nunca encolhe o conteúdo a ponto de torná-lo ilegível; páginas densas rolam. */
const PISO_PROJECAO=0.90;
function ajustaProjecao(){
  const c=document.querySelector('.cena'),co=document.getElementById('corpo');
  if(!c||!co)return;
  c.style.zoom='';
  if(MODO!=='apresentacao')return;
  const cabe=()=>c.scrollHeight<=c.clientHeight+2&&co.scrollHeight<=co.clientHeight+2;
  if(cabe())return;
  let z=1;
  for(let i=0;i<14&&!cabe();i++){z=Math.max(PISO_PROJECAO,z-0.03);c.style.zoom=z;
    if(z<=PISO_PROJECAO)break;}
  if(!cabe())c.style.zoom=PISO_PROJECAO;
}
addEventListener('resize',()=>{if(MODO==='apresentacao')ajustaProjecao();});

/* ---------------- guia do professor: os treze campos ---------------- */
function guia(p){
  const n=document.getElementById('notas');
  if(!p.guia){n.innerHTML='<h3>Guia</h3><p class="nota">Página sem guia registrado.</p>';return;}
  const g=p.guia,c=cap(p.cap),a=aulaDaPagina(p);
  const linhas=[
   ['Módulo e capítulo',`${rotuloModulo(a)} · Capítulo ${c.n}: ${c.nome}`],
   ['Título da página',p.titulo],
   ['Aprendizado único',p.aprendizado],
   ['Tempo previsto',`${p.min} min (exposição ${p.t.exp||0}, exemplo ${p.t.ex||0}, prática ${p.t.prat||0}, discussão ${p.t.disc||0})`],
   ['Função na aula',g.funcao],
   ['Pré-requisito',g.pre],
   ['Condução',g.conducao],
   ['Como ler a tela',g.leitura],
   ['Pergunta para a turma',g.pergunta],
   ['Resposta esperada',g.resposta],
   ['Interação disponível',g.interacao],
   ['Verificação de entendimento',g.verificacao],
   ['Transição',g.transicao]];
  n.innerHTML=`<div style="display:flex;justify-content:space-between;gap:9px">
   <h3>${esc(p.titulo.slice(0,42))}</h3>
   <button class="botao sec min" id="fn">Fechar</button></div>
   <div class="cron" id="cv">00:00</div>
   <dl>${linhas.filter(x=>x[1]).map(x=>`<dt>${esc(x[0])}</dt><dd>${esc(x[1])}</dd>`).join('')}</dl>
   ${(g.erros&&g.erros.length)?`<dl><dt>Erros esperados e intervenção</dt>
    ${g.erros.map(e=>`<dd style="margin-bottom:8px"><b>${esc(e.alt)}</b><br>
     <span class="nota">Confusão: ${esc(e.confusao)}</span><br>
     <span class="nota">Intervenção: ${esc(e.intervencao)}</span></dd>`).join('')}</dl>`
    :'<dl><dt>Erros esperados</dt><dd class="nota">Nenhum erro típico registrado para esta página.</dd></dl>'}`;
  document.getElementById('fn').addEventListener('click',toggleGuia);
  if(CRON.t)pinta();
}
function toggleGuia(){const n=document.getElementById('notas');
  const a=n.classList.toggle('aberto');document.getElementById('bg').setAttribute('aria-pressed',a);}
const CRON={t:null,s:0};
function pinta(){const e=document.getElementById('cv');if(e)
  e.textContent=String(Math.floor(CRON.s/60)).padStart(2,'0')+':'+String(CRON.s%60).padStart(2,'0');}
function cron(){if(CRON.t){clearInterval(CRON.t);CRON.t=null;}
  else{CRON.s=0;CRON.t=setInterval(()=>{CRON.s++;pinta();},1000);
   if(!document.getElementById('notas').classList.contains('aberto'))toggleGuia();}pinta();}

/* ---------------- mapa do curso em painel, chamável a qualquer momento ---------------- */
function painelMapa(){
  const p=LISTA[AT];
  const d=document.createElement('div');
  d.setAttribute('role','dialog');d.setAttribute('aria-label','Mapa do curso');
  d.style.cssText='position:fixed;inset:0;background:rgba(0,32,91,.5);z-index:99;display:flex;'
   +'align-items:center;justify-content:center;padding:18px;overflow:auto';
  d.innerHTML=`<div class="painel" style="max-width:1050px;width:100%;max-height:92vh;overflow:auto">
   <div style="display:flex;justify-content:space-between;gap:9px;align-items:baseline">
    <h3>Onde estamos</h3><button class="botao sec min" data-fc>Fechar</button></div>
   <div class="svgfit" style="margin-top:8px">${mapaCurso(p.cap)}</div>
   <div style="margin-top:10px">${barrasProgresso()}</div></div>`;
  d.querySelector('[data-fc]').addEventListener('click',()=>d.remove());
  d.addEventListener('click',e=>{if(e.target===d)d.remove();});
  document.body.appendChild(d);
}
/* ---------------- fronteira de capítulo: revisão de pré-requisito ---------------- */
let ARRANQUE=Date.now();
function marcaFronteira(de,para){
  if(para.cap<=de.cap)return;
  if(Date.now()-ARRANQUE<4000)return;                 // não interrompe quem chega por endereço direto
  if(pega('aviso_'+para.cap,false))return;            // uma vez por capítulo, por navegador
  const faltam=LISTA.filter(x=>x.cap<para.cap&&!pega('v_'+x.id,false));
  if(faltam.length<3)return;                          // uma ou duas páginas puladas não interrompem
  poe('aviso_'+para.cap,true);
  avisoPrerequisito(cap(para.cap),cap(de.cap),faltam.slice(-8));
}
function avisoPrerequisito(alvo,anterior,faltam){
  const d=document.createElement('div');
  d.setAttribute('role','dialog');d.setAttribute('aria-label','Revisão de pré-requisito');
  d.style.cssText='position:fixed;inset:0;background:rgba(0,32,91,.5);z-index:99;display:flex;'
   +'align-items:center;justify-content:center;padding:18px;overflow:auto';
  d.innerHTML=`<div class="painel" style="max-width:660px;width:100%;max-height:90vh;overflow:auto">
   <h3>Antes do capítulo ${alvo.n}</h3>
   <p class="nota" style="margin-top:6px">Pré-requisito declarado: ${esc(alvo.prereq)}</p>
   <div class="revelacao" style="margin-top:10px"><h4>O que ficou para trás</h4>
    ${faltam.length} página${faltam.length===1?'':'s'} anteriores ainda não
    ${faltam.length===1?'foi visitada':'foram visitadas'}. Você pode seguir mesmo assim; o capítulo
    ${alvo.n} assume esse conteúdo sem redefinir. Este aviso aparece uma única vez por capítulo.</div>
   <p class="nota" style="margin-top:8px">As mais recentes:</p>
   <div style="margin-top:10px;max-height:38vh;overflow:auto">
    ${faltam.map(x=>`<a href="#/${x.id}" style="display:block;margin-bottom:3px;padding:6px 9px;
      border:1px solid var(--regua);border-radius:5px;text-decoration:none;color:var(--ink);
      font-size:13px;background:#fff">${x.cap}.${x.n} &nbsp;${esc(x.titulo)}</a>`).join('')}</div>
   <div class="linhabotoes" style="margin-top:11px">
    <button class="botao" data-ok>Seguir para o capítulo ${alvo.n}</button>
    <button class="botao sec" data-rev>Revisar primeiro</button></div></div>`;
  d.querySelector('[data-ok]').addEventListener('click',()=>d.remove());
  d.querySelector('[data-rev]').addEventListener('click',()=>{
   d.remove();const alvoP=faltam[0];const j=LISTA.findIndex(x=>x.id===alvoP.id);
   if(j>=0){AT=j;location.hash='#/'+alvoP.id;desenha();}});
  d.querySelectorAll('a.pill').forEach(a=>a.addEventListener('click',()=>d.remove()));
  d.addEventListener('click',e=>{if(e.target===d)d.remove();});
  document.body.appendChild(d);
}
/* ---------------- QR por atividade ---------------- */
function urlDaPagina(base,id,aluno){
  try{const u=new URL(base);u.hash='/'+id+(aluno?'?m=aluno':'');return u.toString();}
  catch(e){return null;}
}
function painelQR(){
  const p=LISTA[AT],base=pega('urlPub','');
  const d=document.createElement('div');
  d.setAttribute('role','dialog');d.setAttribute('aria-label','Código QR desta página');
  d.style.cssText='position:fixed;inset:0;background:rgba(0,32,91,.5);z-index:99;display:flex;'
   +'align-items:center;justify-content:center;padding:18px;overflow:auto';
  const corpo=()=>{
   const b=(document.getElementById('qrb')?document.getElementById('qrb').value:base).trim();
   const u=b?urlDaPagina(b,p.id,true):null;
   let miolo;
   if(!b)miolo=`<div class="revelacao ruim"><b>Informe o endereço publicado para ativar o código.</b>
    Enquanto não houver endereço verificado nenhum código é exibido: um QR de exemplo projetado
    levaria a turma a lugar nenhum.</div>`;
   else if(!u||!/^https:/i.test(b))miolo=`<div class="revelacao ruim">O endereço precisa começar com
    <code>https://</code> e ser válido.</div>`;
   else{let g;try{g=qrSvg(u,250,4);}catch(e){g=null;}
    miolo=g?`<div style="text-align:center"><div style="max-width:250px;margin:0 auto;background:#fff;padding:6px">${g}</div>
     <a href="${esc(u)}" style="font-family:var(--mono);font-size:11.5px;word-break:break-all;display:block;margin-top:8px">${esc(u)}</a>
     <div class="linhabotoes" style="justify-content:center;margin-top:9px">
      <button class="botao sec min" id="qrab">Abrir em nova aba</button>
      <button class="botao sec min" id="qramp">Ampliar para projeção</button></div></div>`
     :`<div class="revelacao ruim">Endereço longo demais para gerar um código legível.</div>`;}
   return `<div class="painel" style="max-width:560px;width:100%;max-height:90vh;overflow:auto">
    <h3>Código desta atividade</h3>
    <p class="nota">Abre direto em <b>${esc(p.titulo.slice(0,44))}</b>, no painel do aluno,
    capítulo ${p.cap}, página ${p.n}.</p>
    <div class="ctrl" style="margin-top:10px"><label for="qrb">Endereço público do material</label>
     <input type="text" id="qrb" value="${esc(b)}" placeholder="https://..." inputmode="url"
      style="width:100%;padding:9px;border:1px solid var(--regua);border-radius:5px;
      font-family:var(--mono);font-size:13px"></div>
    <div style="margin-top:10px">${miolo}</div>
    <div class="revelacao" style="margin-top:11px;font-size:13px"><b>Confira antes de projetar.</b>
     Abra o endereço em janela anônima e verifique se ele cai nesta página e no modo aluno.
     Se a plataforma descartar a parte após o <code>#</code>, use o endereço geral e peça navegação
     pelo índice. A verificação feita aqui foi por decodificação de imagem, não por leitura física.</div>
    <div class="linhabotoes" style="margin-top:11px"><button class="botao sec" id="qrfc">Fechar</button></div></div>`;};
  const liga=()=>{
   d.querySelector('#qrfc').addEventListener('click',()=>d.remove());
   const inp=d.querySelector('#qrb');
   inp.addEventListener('change',()=>{poe('urlPub',inp.value.trim());d.innerHTML=corpo();liga();});
   const ab=d.querySelector('#qrab');
   if(ab)ab.addEventListener('click',()=>window.open(urlDaPagina(inp.value.trim(),p.id,true),'_blank','noopener'));
   const am=d.querySelector('#qramp');
   if(am)am.addEventListener('click',()=>{
    const u=urlDaPagina(inp.value.trim(),p.id,true);
    const z=document.createElement('div');
    z.style.cssText='position:fixed;inset:0;background:#fff;z-index:100;display:flex;flex-direction:column;'
     +'align-items:center;justify-content:center;gap:16px;cursor:zoom-out;padding:20px';
    z.innerHTML=`<div style="width:min(70vh,70vw)">${qrSvg(u,880,4)}</div>
     <div style="font-family:var(--mono);font-size:15px;color:#000;word-break:break-all;text-align:center">${esc(u)}</div>
     <div style="font-size:13px;color:#555">clique para fechar</div>`;
    z.addEventListener('click',()=>z.remove());document.body.appendChild(z);});};
  d.innerHTML=corpo();liga();
  d.addEventListener('click',e=>{if(e.target===d)d.remove();});
  document.body.appendChild(d);
}
/* ---------------- navegação por endereço e teclado ---------------- */
function irPara(id,semAviso){
  const p=pagPorId(id);if(!p)return false;
  if(MODO==='apresentacao'&&p.nivel!=='essencial'){MODO='professor';poe('modo',MODO);
   document.body.className='m-estudo';recalculaLista();sincroniza();mapa();}
  const j=LISTA.findIndex(x=>x.id===id);if(j<0)return false;
  const de=LISTA[AT];AT=j;desenha();
  if(!semAviso&&de&&de.cap!==p.cap&&MODO!=='apresentacao')marcaFronteira(de,p);
  return true;
}
addEventListener('hashchange',()=>{
  const id=location.hash.replace(/^#\//,'').split('?')[0];
  if(id&&LISTA[AT]&&id!==LISTA[AT].id)irPara(id);});
addEventListener('keydown',e=>{
  if(/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))return;
  if(e.target.tagName==='BUTTON'&&(e.key===' '||e.key==='Enter'))return;
  const k=e.key.toLowerCase();
  if(k==='arrowright'||k===' '){e.preventDefault();vai(AT+1);}
  else if(k==='arrowleft'){e.preventDefault();vai(AT-1);}
  else if(k==='g'&&MODO!=='aluno')toggleGuia();
  else if(k==='t'&&MODO!=='aluno')cron();
  else if(k==='c')painelMapa();
  else if(k==='m'){const o=['professor','aluno','apresentacao'];setModo(o[(o.indexOf(MODO)+1)%3]);}
  else if(k==='f'){document.fullscreenElement?document.exitFullscreen()
   :document.documentElement.requestFullscreen&&document.documentElement.requestFullscreen();}
  else if(k==='escape'){const n=document.getElementById('notas');
   if(n.classList.contains('aberto'))toggleGuia();}});

