 muda('c11p13',{titulo:'O boosting em uma proposta',
  aprendizado:'Reconstruir a PD do cliente VAL-0187 acumulando correções em log-odds e convertendo o total pela sigmoide.',
  apoio:'As árvores pequenas não votam e seus valores não são pontos percentuais. Cada saída h é multiplicada por η e somada à escala F.',
  visual:()=>`<div class="nv"><div class="nv-boost-lab"><div class="nv-boost-case"><small>MESMO CLIENTE DA COMPARAÇÃO</small><h3>${FONTE_CURSO.cliente.id}</h3><div class="facts">utilização ${FONTE_CURSO.cliente.utilizacao}% · atraso ${FONTE_CURSO.cliente.atraso} dias · comprometimento ${FONTE_CURSO.cliente.comprometimento}%</div><div class="nv-boost-state"><div><small>log-odds acumulado F</small><strong id="nv-boost-f">—</strong></div><div><small>PD = sigmoide(F)</small><strong id="nv-boost-p">—</strong></div></div></div><div class="nv-boost-main"><div class="nv-boost-controls"><button type="button" data-boost-move="-1" aria-label="Iteração anterior">←</button><input id="nv-boost-step" type="range" min="0" max="4" step="1" value="0" aria-label="Iteração do boosting"><button type="button" data-boost-move="1" aria-label="Próxima iteração">→</button></div><b id="nv-boost-label">iteração 0 de 4</b><table class="nv-boost-table"><thead><tr><th>m</th><th>h<sub>m</sub>(x)</th><th>ηh<sub>m</sub>(x)</th><th>F<sub>m</sub>(x)</th><th>PD<sub>m</sub>(x)</th></tr></thead><tbody id="nv-boost-body">${BOOSTING_PD.map(s=>`<tr data-m="${s.m}"><th>${s.m}</th><td class="num">${s.h===null?'—':s.h.toFixed(2).replace('.',',')}</td><td class="num">${s.delta===null?'—':(s.delta>=0?'+':'')+s.delta.toFixed(2).replace('.',',')}</td><td class="num">${s.f.toFixed(3).replace('.',',')}</td><td class="num">${(100*s.p).toFixed(2).replace('.',',')}%</td></tr>`).join('')}</tbody></table><div class="nv-boost-read" id="nv-boost-read" aria-live="polite"></div></div></div><div class="formula" data-latex="F_m(x)=F_{m-1}(x)+\\eta h_m(x),\\quad PD_m(x)=\\sigma(F_m(x))">F m igual a F anterior mais eta vezes h; PD igual a sigmoide de F</div><div class="nv-caption"><b>Resultado calculado</b><span>9,56% → 11,54% → 12,93% → 12,49% → <strong>13,39%</strong>. A terceira árvore reduz o risco; nenhuma etapa soma diretamente pontos percentuais.</span></div></div>`,init:ligaBoostingPD,
  guia:undefined});

