 const woeEx=[{rot:'mesma proporção',bom:.50,mau:.50},{rot:'mais bons',bom:.70,mau:.30},{rot:'mais maus',bom:.25,mau:.75}];
 const woeBloco=a=>{const w=Math.log(a.bom/a.mau);return `<div class="v13-cena-lado"><small>concentração relativa</small><span class="big">${fmt(w,3)}</span><p>WoE = ln(% bons / % maus)</p></div><div class="v13-cena-main"><div class="v13-compare"><div><small>bons na faixa</small><strong>${pct(a.bom,0)}</strong></div><span class="vs">÷</span><div><small>maus na faixa</small><strong>${pct(a.mau,0)}</strong></div></div><p>${Math.abs(w)<.001?'A faixa aparece na mesma proporção nos dois grupos: não separa.':w>0?'Sinal positivo: a faixa concentra relativamente mais bons.':'Sinal negativo: a faixa concentra relativamente mais maus.'}</p></div>`;};
