 const pLossV13=[.02,.125,.30,.70];
 const perdaConst=p=>-(Math.log(p)+7*Math.log(1-p))/8;
 const pLossBloco=p=>`<div class="v13-cena-lado"><small>PD constante nas 8 propostas</small><span class="big">${pct(p,1)}</span><p>1 default observado</p></div><div class="v13-cena-main"><div class="v13-metricas"><div><small>perda média</small><strong>${fmt(perdaConst(p),4)}</strong></div><div><small>frequência observada</small><strong>12,5%</strong></div><div><small>distância ao mínimo</small><strong>${pct(Math.abs(p-.125),1)}</strong></div></div><p>${Math.abs(p-.125)<.001?'O mínimo coincide com a frequência do grupo: uma em oito.':'A PD se afasta da frequência observada e a log loss aumenta.'}</p></div>`;
 muda('c2p11',{titulo:'A perda encontra a frequência do grupo',aprendizado:'Ver por que a PD constante que minimiza a log loss é a frequência observada do evento.',apoio:'Teste quatro palpites para um grupo com um default em oito propostas.',visual:()=>`<div class="v13-interativo"><div class="v13-tabs">${pLossV13.map((p,i)=>`<button type="button" data-v13-ploss data-i="${i}" class="${i===0?'ativo':''}">${pct(p,1)}</button>`).join('')}</div><div class="v13-cena" id="v13-ploss-out">${pLossBloco(pLossV13[0])}</div><div class="formula" data-latex="\\mathcal L(p)=-\\frac{\\ln p+7\\ln(1-p)}{8}">perda = −[ln(p) + 7 ln(1−p)]/8</div></div>`,init:()=>ligaTabs('[data-v13-ploss]','#v13-ploss-out',i=>pLossBloco(pLossV13[i]))});

 const xyV13=[[1,2],[2,3],[3,4.5],[4,5],[5,8],[6,8.5],[7,9],[8,12]];
 muda('c6p3',{titulo:'Oito pontos, uma tendência e erros locais',aprendizado:'Reconhecer regressão como a tarefa de prever um número e medir o erro na própria escala de y.',apoio:'Clique num ponto: o gráfico destaca a observação e mostra o erro em relação à previsão inicial 6,5.',visual:()=>`<div class="v13-interativo"><div class="v13-cena"><div class="v13-cena-lado"><small>previsão inicial</small><span class="big">6,5</span><p>a média dos oito valores</p></div><div class="v13-cena-main"><svg viewBox="0 0 620 260" role="img" aria-label="oito pontos de regressão" style="width:100%;max-height:270px"><line x1="45" y1="225" x2="590" y2="225" stroke="#9AA5B2"/><line x1="45" y1="20" x2="45" y2="225" stroke="#9AA5B2"/><line x1="45" y1="115" x2="590" y2="115" stroke="var(--ouro)" stroke-dasharray="7 5"/>${xyV13.map((d,i)=>`<circle tabindex="0" role="button" data-v13-xy="${i}" cx="${55+i*72}" cy="${225-d[1]*16}" r="9" fill="var(--cap)"/><text x="${55+i*72}" y="245" text-anchor="middle" font-size="11">${d[0]}</text>`).join('')}<text x="590" y="108" text-anchor="end" font-size="11">F₀ = 6,5</text></svg></div></div><div class="v13-alerta" id="v13-xy-out"><b>Escolha um ponto.</b> O erro é y − 6,5 nesta primeira rodada.</div></div>`,init:()=>{const out=document.getElementById('v13-xy-out');document.querySelectorAll('[data-v13-xy]').forEach((b,i)=>b.addEventListener('click',()=>{const d=xyV13[i],e=d[1]-6.5;out.innerHTML=`<b>x=${d[0]}, y=${String(d[1]).replace('.',',')}.</b> Erro inicial: ${e>=0?'+':''}${fmt(e,1)}. A próxima árvore tenta explicar esse erro.`;}));}});

 muda('c6p12',{titulo:'O resíduo y − p vira o alvo da próxima árvore',aprendizado:'Perceber que casos já bem previstos produzem resíduos pequenos e influenciam menos a correção seguinte.',apoio:'Escolha o desfecho e mova a PD. Observe o alvo da árvore se aproximar de zero quando a previsão acerta.',visual:()=>`<div class="v13-interativo"><div class="v13-tabs"><button type="button" data-v13-y="0" class="ativo">y = 0 · pagou</button><button type="button" data-v13-y="1">y = 1 · default</button></div><div class="v13-cena"><div class="v13-cena-lado"><small>PD atual</small><span class="big" id="v13-res-p">50%</span><input id="v13-res-range" type="range" min="1" max="99" value="50" style="width:100%"></div><div class="v13-cena-main"><h3>Alvo da próxima árvore</h3><div class="v13-metricas"><div><small>y</small><strong id="v13-res-y">0</strong></div><div><small>p</small><strong id="v13-res-p2">0,50</strong></div><div><small>y − p</small><strong id="v13-res-r">−0,50</strong></div></div><p id="v13-res-texto">A previsão ainda dá 50% a quem pagou: há correção negativa importante.</p></div></div><div class="formula" data-latex="r_i^{(m)}=y_i-p_i^{(m-1)}">resíduo na iteração m = y − p da iteração anterior</div></div>`,init:()=>{let y=0;const range=document.getElementById('v13-res-range');const atualiza=()=>{const p=Number(range.value)/100,r=y-p;document.getElementById('v13-res-p').textContent=pct(p,0);document.getElementById('v13-res-p2').textContent=fmt(p,2);document.getElementById('v13-res-y').textContent=y;document.getElementById('v13-res-r').textContent=(r>=0?'+':'')+fmt(r,2);document.getElementById('v13-res-texto').textContent=Math.abs(r)<.15?'Caso já bem previsto: influência pequena na correção seguinte.':'Caso ainda mal previsto: a árvore recebe uma correção relevante.';};document.querySelectorAll('[data-v13-y]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-v13-y]').forEach(x=>x.classList.remove('ativo'));b.classList.add('ativo');y=Number(b.dataset.v13Y);atualiza();}));range.addEventListener('input',atualiza);atualiza();}});

 const paresAuc=[{d:7.77,a:22.39,ok:false},{d:7.77,a:3.25,ok:true},{d:20.44,a:10.78,ok:true},{d:16.10,a:22.39,ok:false}];
 const parAuc=x=>`<div class="v13-cena-lado"><small>par default × adimplente</small><span class="big">${x.ok?'1':'0'}</span><p>${x.ok?'par corretamente ordenado':'par invertido'}</p></div><div class="v13-cena-main"><div class="v13-compare"><div><small>PD do default</small><strong>${String(x.d).replace('.',',')}%</strong></div><span class="vs">${x.ok?'&gt;':'&lt;'}</span><div><small>PD do adimplente</small><strong>${String(x.a).replace('.',',')}%</strong></div></div><p>A AUC é a proporção de pares default–adimplente corretamente ordenados.</p></div>`;
 muda('c7p5',{titulo:'AUC é uma contagem de pares',aprendizado:'Interpretar a AUC como a chance de um default receber risco maior que um adimplente escolhido ao acaso.',apoio:'Abra quatro pares representativos. No exemplo completo, 12 dos 20 pares estão na ordem correta.',visual:()=>`<div class="v13-interativo"><div class="v13-tabs">${paresAuc.map((x,i)=>`<button type="button" data-v13-par data-i="${i}" class="${i===0?'ativo':''}">par ${i+1}</button>`).join('')}</div><div class="v13-cena" id="v13-par-out">${parAuc(paresAuc[0])}</div><div class="v13-metricas"><div><small>exemplo didático</small><strong>12/20 = 0,600</strong></div><div><small>OOT real</small><strong>0,7257</strong></div><div><small>pares no OOT</small><strong>53.136</strong></div></div><div class="formula" data-latex="AUC=\\frac{\\text{pares corretos}+0{,}5\\,\\text{empates}}{\\text{pares default--adimplente}}">AUC = (pares corretos + 0,5 × empates) / todos os pares default–adimplente</div></div>`,init:()=>ligaTabs('[data-v13-par]','#v13-par-out',i=>parAuc(paresAuc[i]))});

 const clientesComite=[{rot:'Helena',pd:'44,9%',valor:'−R$ 2.618',zona:'recusa',frase:'Risco alto e valor negativo; a política aponta recusa.'},{rot:'Rogério',pd:'5,2%',valor:'R$ 1.261',zona:'automática',frase:'Risco baixo e valor positivo; a política permite aprovação automática.'},{rot:'Dalva',pd:'21,9%',valor:'−R$ 817',zona:'revisão',frase:'Caso intermediário; a política envia para revisão, não para decisão silenciosa.'}];
 const clienteComite=x=>`<div class="v13-cena-lado"><small>${x.rot}</small><span class="big">${x.pd}</span><p>PD em 12 meses</p></div><div class="v13-cena-main"><div class="v13-metricas"><div><small>resultado esperado</small><strong>${x.valor}</strong></div><div><small>zona</small><strong>${x.zona}</strong></div><div><small>cadeia</small><strong>PD → valor → ação</strong></div></div><p>${x.frase}</p></div>`;
 muda('c10p2',{titulo:'Três clientes, três zonas da política',aprendizado:'Reconstruir a decisão em três elos: previsão de risco, resultado econômico e regra de política.',apoio:'Escolha um cliente. O objetivo é explicar a cadeia inteira, não apenas repetir a PD.',visual:()=>`<div class="v13-interativo"><div class="v13-tabs">${clientesComite.map((x,i)=>`<button type="button" data-v13-cli data-i="${i}" class="${i===0?'ativo':''}">${x.rot}</button>`).join('')}</div><div class="v13-cena" id="v13-cli-out">${clienteComite(clientesComite[0])}</div><div class="v13-alerta"><b>O que mudou desde o capítulo 1?</b> A pessoa e os dados são os mesmos; agora o critério está declarado e pode ser auditado.</div></div>`,init:()=>ligaTabs('[data-v13-cli]','#v13-cli-out',i=>clienteComite(clientesComite[i]))});

 const quadroComite=[{rot:'Ordenação',pergunta:'Quem deve ficar acima na fila de risco?',log:'AUC 0,7257',gbm:'AUC 0,6958',dono:'modelagem + validação'},{rot:'Calibração',pergunta:'As probabilidades correspondem às frequências?',log:'Brier 0,09128',gbm:'Brier 0,09491',dono:'risco + contabilidade'},{rot:'Economia',pergunta:'Qual carteira cria valor sob a política?',log:'R$ 607 mil',gbm:'R$ 339 mil',dono:'negócio + risco'},{rot:'Governança',pergunta:'A decisão pode ser explicada e mantida?',log:'motivo exato',gbm:'motivo aproximado',dono:'conformidade + operações'}];
 const quadroBloco=x=>`<div class="v13-cena-lado"><small>pergunta do comitê</small><span class="big">${x.rot}</span><p>${x.dono}</p></div><div class="v13-cena-main"><h3>${x.pergunta}</h3><div class="v13-compare"><div><small>logística + WoE</small><strong>${x.log}</strong></div><span class="vs">×</span><div><small>boosting calibrado</small><strong>${x.gbm}</strong></div></div></div>`;
 muda('c10p3',{titulo:'O quadro de decisão do comitê',aprendizado:'Integrar ordenação, calibração, economia e governança sem reduzir a escolha a uma única métrica.',apoio:'Troque a pergunta do comitê. Cada dimensão tem número, responsável e consequência distintos.',visual:()=>`<div class="v13-interativo"><div class="v13-tabs">${quadroComite.map((x,i)=>`<button type="button" data-v13-quadro data-i="${i}" class="${i===0?'ativo':''}">${x.rot}</button>`).join('')}</div><div class="v13-cena" id="v13-quadro-out">${quadroBloco(quadroComite[0])}</div><div class="v13-alerta"><b>Recomendação defensável:</b> manter a logística como principal. A evidência de AUC é limítrofe, e simplicidade, economia e governança reforçam a escolha.</div></div>`,init:()=>ligaTabs('[data-v13-quadro]','#v13-quadro-out',i=>quadroBloco(quadroComite[i]))});

