function inicia(){
  narrativaVisualV6();
  trabalhoFinalV10();
  experienciaV13();
  const q=new URLSearchParams(location.hash.split('?')[1]||'');
  if(q.get('m')==='aluno')MODO='aluno';
  if(q.get('m')==='projecao')MODO='apresentacao';
  recalculaLista();
  casca();
  aplicaClasseModo();
  mapa();
  const id=location.hash.replace(/^#\//,'').split('?')[0];
  if(id){const j=LISTA.findIndex(p=>p.id===id);if(j>=0)AT=j;}
  desenha();
  ARRANQUE=Date.now();
  /* registra visita para o progresso e para a revisão de pré-requisito */
  setInterval(()=>{const p=LISTA[AT];if(p&&!pega('v_'+p.id,false))poe('v_'+p.id,true);},4000);
}
